window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[75]={"id":"075","numero":75,"titre":"Addiction au tabac","objectifs":[{"id":"75-1","rang":"A","rubrique":"Définition","titre":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","contenu":"<p>Le <span class=\"kw-etio\">tabagisme</span> est l'inhalation de la fumée de <span class=\"kw-etio\">tabac</span>, volontaire ou involontaire. Il n'existe <strong>aucun seuil de consommation sans risque</strong> — <span class=\"kw-clinique\">les</span> complications concernent les trois modalités d'exposition.</p>\n      <table >\n        <thead><tr><th>Exposition</th><th>Principaux risques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Tabagisme actif</span><br>(le fumeur inhale sa propre fumée)</td>\n            <td>\n              <strong>Cancers :</strong> <span class=\"kw-alerte\">poumon</span> ; voies aéro-digestives supérieures ; vessie ; pancréas<br>\n              <strong>Cardiovasculaire :</strong> <span class=\"kw-etio\">HTA</span> ; <span class=\"kw-alerte\">infarctus du myocarde</span> ; AOMI ; <span class=\"kw-etio\">AVC</span><br>\n              <strong>Respiratoire :</strong> <span class=\"kw-etio\">BPCO</span> ; emphysème<br>\n              <strong>Reproduction :</strong> baisse de la fertilité ; troubles de la <span class=\"kw-ci\">grossesse</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Tabagisme passif</span><br>(non-fumeur exposé à la fumée ambiante)</td>\n            <td>\n              <strong>Adulte :</strong> cancer pulmonaire (RR <span class=\"kw-chiffre\">+ 25 %</span>) ; décès cardiovasculaire (RR <span class=\"kw-chiffre\">+ 20-30 %</span>) — risque présent <strong>même à faibles doses</strong><br>\n              <strong>Femme enceinte :</strong> <span class=\"kw-etio\">RCIU</span> ; accouchement prématuré<br>\n              <strong>Enfant / nourrisson :</strong> otites et infections ORL ; infections pulmonaires ; <span class=\"kw-etio\">asthme</span> ; <span class=\"kw-alerte\">mort subite du nourrisson</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Tabagisme in utero</span><br>(exposition fœtale)</td>\n            <td>\n              <span class=\"kw-alerte\">Fausse couche</span> ; mort fœtale in utero ; <span class=\"kw-alerte\">rupture</span> prématurée des membranes ; accouchement prématuré ; <span class=\"kw-etio\">RCIU</span> ; <span class=\"kw-ci\">grossesse</span> extra-utérine ; placenta praevia ; hématome rétroplacentaire\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Le <span class=\"kw-def\">courant secondaire</span> (fumée s'échappant du bout incandescent de la c<span class=\"kw-chiffre\">iga</span>rette) est <strong>plus <span class=\"kw-etio\">toxique</span></strong> que le courant primaire inhalé par le fumeur : plus concentré en <span class=\"kw-bio\">monoxyde de carbone</span>, goudrons et cancérigènes, et non filtré.\n      </div>","frequence":1},{"id":"75-2","rang":"A","rubrique":"Définition","titre":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d’évaluer cette dépendance","contenu":"<p>Le <span class=\"kw-etio\">tabac</span> entraîne une <span class=\"kw-def\">dépendance</span> à plusieurs registres, qu'il faut tous évaluer. La <span class=\"kw-def\">dépendance selon la CIM-10</span> est définie par la présence d'<span class=\"kw-chiffre\">≥ 3 manifestations</span> au cours de la dernière année.</p>\n      <table >\n        <thead><tr><th>Type de dépendance</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">CIM-10</span><br>(<span class=\"kw-chiffre\">≥ 3</span> critères / <span class=\"kw-chiffre\">12 mois</span>)</td>\n            <td><span class=\"kw-clinique\">Désir compulsif</span> de consommer ; difficultés à contrôler l'usage (début, quantité, arrêt) ; <span class=\"kw-def\">syndrome de sevrage</span> à l'arrêt ; <span class=\"kw-clinique\">tolérance</span> (augmentation des doses) ; désintérêt pour <span class=\"kw-clinique\">les</span> autres plaisirs ; poursuite malgré les conséquences néfastes</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Physique</span> (pharmacologique)</td>\n            <td>Liée directement à la <span class=\"kw-ttt\">nicotine</span> : pic de concentration rapide vers le cerveau (« <strong>effet shoot</strong> ») ; fixation sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">récepteurs cholinergiques nicotiniques</span> ; stimulation du système de récompense par libération de <span class=\"kw-bio\">dopamine</span>. S'évalue par le <span class=\"kw-def\">test de Fagerström</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Psychologique</span></td>\n            <td>Liée aux « effets positifs » associés à la c<span class=\"kw-chiffre\">iga</span>rette (se relaxer, réfléchir, effet coupe-faim). Reflétée par le <span class=\"kw-clinique\">craving</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Comportementale</span> (sociale)</td>\n            <td>Liée aux situations répétées associées à la c<span class=\"kw-chiffre\">iga</span>rette (moments de convivialité ; association au café, à l'<span class=\"kw-etio\">alcool</span>, au cannabis) déclenchant une envie « réflexe ». Reflétée par le <span class=\"kw-clinique\">craving</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p>L'<strong>évaluation</strong> de la dépendance physique repose sur le <span class=\"kw-def\">test de Fagerström</span> ; <span class=\"kw-clinique\">les</span> dépendances psychologique et comportementale s'apprécient sur la présence de <span class=\"kw-clinique\">craving</span>, qui est un <span class=\"kw-alerte\">facteur de risque de rechute</span>. Le détail du test est développé dans les modalités de diagnostic de la dépendance.</p>","frequence":3},{"id":"75-3","rang":"B","rubrique":"Définition","titre":"Connaître la définition de la cigarette électronique","contenu":"<p>La <span class=\"kw-def\">cigarette électronique</span> (vapoteuse, vaporette, vape ; aussi « vaporisateur personnel » ou « système électronique de délivrance de la nicotine ») est un dispositif d'<strong>inhalation sans combustion</strong>. Elle peut être considérée comme une <span class=\"kw-ttt\">aide au sevrage</span>.</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td>Composition</td><td>Batterie ; atomiseur ; cartouche / réservoir / clearomiseur contenant une résistance et rempli d'un e-liquide</td></tr>\n          <tr><td>E-liquide</td><td><span class=\"kw-ttt\">Nicotine</span> à concentration variable (<span class=\"kw-chiffre\">0-20 mg/mL</span>) ; additifs et substances aromatiques ; propylène glycol et glycérine végétale (le propylène glycol n'est pas <span class=\"kw-etio\">toxique</span> par inhalation ; réactions allergiques possibles)</td></tr>\n          <tr><td>Fonctionnement</td><td>Inspiration → la batterie chauffe la résistance puis le liquide → aérosolisation et inhalation d'une vapeur</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'<strong>absence de combustion</strong> explique l'absence de production de <span class=\"kw-bio\">monoxyde de carbone</span> et de <span class=\"kw-alerte\">goudron</span> — c'est le point discriminant face à la c<span class=\"kw-chiffre\">iga</span>rette classique. La cigarette électronique n'est <span class=\"kw-ci\">pas recommandée chez la femme enceinte ni chez le non-fumeur</span>.\n      </div>","frequence":0},{"id":"75-4","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la toxicité de la nicotine, des goudrons et de la fumée de tabac","contenu":"<p>La fumée de <span class=\"kw-etio\">tabac</span> est un <span class=\"kw-def\">aérosol</span> (gaz + particules de <span class=\"kw-clinique\">diamètre</span> médian <span class=\"kw-chiffre\">0,3 µm</span>) formé à <span class=\"kw-chiffre\">1 000-1 500 °C</span>. Une c<span class=\"kw-chiffre\">iga</span>rette contient environ <span class=\"kw-chiffre\">7 000 composés</span>, dont au moins <span class=\"kw-chiffre\">70 cancérigènes</span>.</p>\n      <table >\n        <thead><tr><th>Constituant</th><th>Toxicité</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Nicotine</span></td><td>Principal agent de la <span class=\"kw-def\">dépendance</span> (effet shoot). <strong>Peu <span class=\"kw-etio\">toxique</span></strong> : non considérée comme cancérigène, pas de rôle spécifique dans <span class=\"kw-clinique\">les</span> complications cardiovasculaires</td></tr>\n          <tr><td><span class=\"kw-alerte\">Goudrons</span> (HAP)</td><td>Principal cancérigène : modifient <span class=\"kw-clinique\">les</span> cellules épithéliales. Aussi : N-nitrosamines, amines aromatiques, benzène, composés radioactifs (polonium), formaldéhyde → liaison à l'ADN, mutations, inflammation, stress oxydatif</td></tr>\n          <tr><td>Toxicité cardiovasculaire</td><td><strong>Particules :</strong> rôle dans la <span class=\"kw-alerte\">thrombose artérielle</span> (mais pas veineuse)<br><strong>Monoxyde de carbone :</strong> lésions endothéliales ; <span class=\"kw-clinique\">hypoxie</span> par fixation sur l'<span class=\"kw-bio\">hémoglobine</span></td></tr>\n          <tr><td>Toxicité pulmonaire</td><td><span class=\"kw-alerte\">Radicaux libres</span> : dégradation de la paroi alvéolaire ; inhibition des enzymes protectrices</td></tr>\n          <tr><td>Autres</td><td>Métaux lourds (cadmium, plomb, chrome, mercure) ; agents de saveur</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> La <span class=\"kw-ttt\">nicotine</span> est responsable de la <strong>dépendance</strong> mais n'est <span class=\"kw-ci\">ni cancérigène ni cardiotoxique</span> de façon spécifique. Ce sont <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">goudrons</span> (cancers) et le <span class=\"kw-bio\">monoxyde de carbone</span> + les particules (atteinte cardiovasculaire) qui portent la toxicité.\n      </div>","frequence":1},{"id":"75-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître le mécanisme d'atteinte artérielle (thrombogénicité, vasomotricité, inflammation)","contenu":"<p>L'atteinte artérielle du <span class=\"kw-etio\">tabac</span> repose sur quatre mécanismes convergents — la <span class=\"kw-ttt\">nicotine</span> n'y joue <strong>aucun rôle spécifique</strong> (effets cardiovasculaires absents avec <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">substituts nicotiniques</span>, induits uniquement par la combustion).</p>\n      <table >\n        <thead><tr><th>Mécanisme</th><th>Conséquence</th></tr></thead>\n        <tbody>\n          <tr><td>Athérogenèse</td><td>Abaissement du <span class=\"kw-bio\">HDL-cholestérol</span> → facilite le développement des <span class=\"kw-alerte\">lésions athéroscléreuses</span> (<span class=\"kw-clinique\">les</span> carcinogènes favorisent aussi l'<span class=\"kw-etio\">athérome</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Thrombogénicité</span></td><td>Augmentation de l'<span class=\"kw-bio\">agrégation plaquettaire</span>, du <span class=\"kw-bio\">fibrinogène</span> et de la <span class=\"kw-bio\">viscosité sanguine</span> → <span class=\"kw-alerte\">risque thrombotique</span> artériel</td></tr>\n          <tr><td><span class=\"kw-def\">Vasomotricité</span></td><td>Altération de la vasomotricité artérielle endothélium-dépendante → <span class=\"kw-alerte\">spasme coronarien</span></td></tr>\n          <tr><td>Hypoxie / inflammation</td><td>Concentration importante de <span class=\"kw-bio\">monoxyde de carbone</span> circulant → lésions endothéliales et défaut de transport de l'oxygène par l'<span class=\"kw-bio\">hémoglobine</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire</em></p>","frequence":1},{"id":"75-6","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","contenu":"<table >\n        <thead><tr><th>Indicateur</th><th>Ordre de grandeur</th></tr></thead>\n        <tbody>\n          <tr><td>Âge de la 1ʳᵉ c<span class=\"kw-chiffre\">iga</span>rette</td><td><span class=\"kw-chiffre\">≈ 14 ans</span> (stable)</td></tr>\n          <tr><td>Âge du début d'une consommation quotidienne</td><td><span class=\"kw-chiffre\">≈ 15 ans</span></td></tr>\n          <tr><td>Fumeurs réguliers présentant des signes de dépendance</td><td><span class=\"kw-chiffre\">≈ 50 %</span></td></tr>\n          <tr><td>Fumeurs qui mourront prématurément d'une maladie due au <span class=\"kw-etio\">tabac</span></td><td><span class=\"kw-chiffre\">≈ 50 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> mondiale</td><td><span class=\"kw-alerte\">1 décès sur 10</span> dans le monde</td></tr>\n          <tr><td><span class=\"kw-def\">Mortalité</span> française</td><td><span class=\"kw-alerte\">75 000 décès prématurés / an</span> — <strong>1ʳᵉ cause de décès évitable</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le <strong><span class=\"kw-def\">facteur de risque</span> le plus important</strong> de complications est la <span class=\"kw-alerte\">durée d'intoxication</span> : doubler la dose multiplie le risque de cancer par 2, mais doubler la durée le multiplie par 16 à 23.\n      </div>","frequence":0},{"id":"75-7","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les tendances épidémiologiques du tabagisme au cours du temps","contenu":"<ul>\n        <li>Le <span class=\"kw-etio\">tabagisme</span> quotidien a connu une <strong>diminution</strong> : <span class=\"kw-chiffre\">-4,5 %</span> entre 2014 et 2019, <span class=\"kw-chiffre\">-12 %</span> entre 2016 et 2018.</li>\n        <li>Cette baisse s'explique par la <span class=\"kw-chiffre\">hausse des prix</span>, le <strong>paquet neutre</strong> et l'opération « <strong>Mois sans <span class=\"kw-etio\">tabac</span></strong> ».</li>\n        <li><span class=\"kw-alerte\">Ré-augmentation depuis 2020</span>, possiblement attribuable à la pandémie de SARS-CoV-2.</li>\n      </ul>","frequence":0},{"id":"75-8","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie du tabagisme chez les hommes et les femmes","contenu":"<p>Le <span class=\"kw-etio\">tabagisme</span> est à <strong>prédominance masculine</strong>. En France, <span class=\"kw-def\">prévalence</span> chez <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">18-75 ans : 33 %</span>.</p>\n      <table >\n        <thead><tr><th>Indicateur</th><th>Hommes</th><th>Femmes</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Tabagisme</span> (toutes formes)</td><td><span class=\"kw-chiffre\">35 %</span></td><td><span class=\"kw-chiffre\">25 %</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Tabagisme</span> quotidien</td><td><span class=\"kw-chiffre\">27,5 %</span></td><td><span class=\"kw-chiffre\">20,7 %</span></td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li>La diminution du <span class=\"kw-etio\">tabagisme</span> est <strong>plus rapide chez <span class=\"kw-clinique\">les</span> hommes</strong>, à tous les âges.</li>\n        <li>Chez <span class=\"kw-clinique\">les</span> femmes : diminution chez les <span class=\"kw-chiffre\">&lt; 55 ans</span>, mais <span class=\"kw-alerte\">augmentation chez les 55-75 ans</span> (arrivée dans ces tranches d'âge des générations de femmes ayant commencé à fumer à partir des années 1960).</li>\n      </ul>","frequence":0},{"id":"75-9","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie du tabagisme chez les jeunes","contenu":"<p>La consommation de <span class=\"kw-etio\">tabac</span> chez <span class=\"kw-clinique\">les</span> jeunes est en <strong>baisse importante</strong>.</p>\n      <table >\n        <thead><tr><th>Population</th><th>Tendance</th></tr></thead>\n        <tbody>\n          <tr><td>Élèves de 3ᵉ — expérimentation</td><td><span class=\"kw-chiffre\">51,8 %</span> (2010) → <span class=\"kw-chiffre\">29,1 %</span> (2021)</td></tr>\n          <tr><td>Élèves de 3ᵉ — usage quotidien</td><td><span class=\"kw-chiffre\">15,6 %</span> (2010) → <span class=\"kw-chiffre\">3,7 %</span> (2021)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">17 ans</span> — usage quotidien</td><td><span class=\"kw-chiffre\">32,4 %</span> (2014) → <span class=\"kw-chiffre\">25,1 %</span> (2017)</td></tr>\n          <tr><td>C<span class=\"kw-chiffre\">iga</span>rette électronique (3ᵉ)</td><td><span class=\"kw-chiffre\">34,2 %</span> d'expérimentateurs (2021)</td></tr>\n          <tr><td>Chicha (3ᵉ)</td><td>En recul : expérimentation <span class=\"kw-chiffre\">26,2 %</span> (2018) → <span class=\"kw-chiffre\">20 %</span> (2021)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"75-10","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie du tabagisme chez la femme enceinte","contenu":"<p>Environ <span class=\"kw-chiffre\">50 %</span> des femmes enceintes <strong>poursuivent le <span class=\"kw-etio\">tabagisme</span></strong> au cours de la <span class=\"kw-ci\">grossesse</span>.</p>\n      <p>La poursuite est plus fréquente parmi <span class=\"kw-clinique\">les</span> femmes les <strong>plus jeunes</strong> et les <strong>moins diplômées</strong>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 27 — Prévention risques fœtaux</em></p>","frequence":0},{"id":"75-11","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les modes de consommation du tabac","contenu":"<table >\n        <thead><tr><th>Mode</th><th>Produits</th></tr></thead>\n        <tbody>\n          <tr>\n            <td>Inhalation après <span class=\"kw-def\">combustion</span></td>\n            <td><strong>Combustion à haute température :</strong> chicha (pipe à eau) ; c<span class=\"kw-chiffre\">iga</span>rettes manufacturées et roulées ; cigarillos ; cigare ; pipe<br><strong>Combustion incomplète :</strong> produits de <span class=\"kw-etio\">tabac</span> chauffé — à <span class=\"kw-alerte\">considérer comme des cigarettes</span> (ne pas confondre avec la cigarette électronique)</td>\n          </tr>\n          <tr>\n            <td>Inhalation <span class=\"kw-def\">sans combustion</span></td>\n            <td>C<span class=\"kw-chiffre\">iga</span>rette électronique ; <em>puffs</em> (cigarettes électroniques jetables) ; <span class=\"kw-etio\">tabac</span> à priser (sniffé)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Ingestion</span></td>\n            <td><em>Snus</em> : <span class=\"kw-etio\">tabac</span> humide en sachet placé entre gencive et lèvre — <span class=\"kw-ci\">vente interdite en Europe</span> (sauf Suède) ; <span class=\"kw-etio\">tabac</span> à chiquer</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"75-12","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’ordre de grandeur du nombre de cas de cancer liés au tabac","contenu":"<p>Le <span class=\"kw-etio\">tabac</span> est le <strong>1ᵉʳ <span class=\"kw-def\">facteur de risque</span> évitable de <span class=\"kw-def\">mortalité</span> précoce par cancer</strong>, en France et dans le monde.</p>\n      <table >\n        <thead><tr><th>Indicateur</th><th>Ordre de grandeur</th></tr></thead>\n        <tbody>\n          <tr><td>Part des cancers attribuables au <span class=\"kw-etio\">tabac</span></td><td><span class=\"kw-chiffre\">≈ 25 %</span> des cancers</td></tr>\n          <tr><td>Décès par cancer dus au <span class=\"kw-etio\">tabac</span> / an (France)</td><td><span class=\"kw-alerte\">≈ 46 000 à 46 500</span></td></tr>\n          <tr><td>… dont cancers du poumon</td><td><span class=\"kw-chiffre\">≈ 32 000</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Il n'existe <strong>pas de seuil de consommation sans risque</strong> — même le <span class=\"kw-etio\">tabagisme passif</span> augmente le risque de cancer.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon · 290 — Epidémiologie cancers</em></p>","frequence":1},{"id":"75-13","rang":"A","rubrique":"Epidémiologie","titre":"Connaître la part du tabac dans la mortalité en France","contenu":"<table >\n        <thead><tr><th>Indicateur</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td>Décès prématurés / an dus au <span class=\"kw-etio\">tabac</span></td><td><span class=\"kw-alerte\">75 000</span></td></tr>\n          <tr><td>Part des décès chez l'<strong>homme</strong></td><td><span class=\"kw-chiffre\">20 %</span></td></tr>\n          <tr><td>Part des décès chez la <strong>femme</strong></td><td><span class=\"kw-chiffre\">7 %</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le <span class=\"kw-etio\">tabac</span> est la <strong>1ʳᵉ cause de décès évitable</strong> en France.\n      </div>","frequence":0},{"id":"75-14","rang":"A","rubrique":"Epidémiologie","titre":"Connaître la mortalité liée au tabagisme actif","contenu":"<p>Un fumeur sur deux (<span class=\"kw-chiffre\">≈ 50 %</span>) mourra prématurément d'une maladie due au <span class=\"kw-etio\">tabac</span>. Répartition des causes de décès liées au <span class=\"kw-etio\">tabac</span> (2015) :</p>\n      <table >\n        <thead><tr><th>Cause</th><th>Décès / an</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Cancers</span></td><td><span class=\"kw-chiffre\">≈ 46 000</span> (dont ≈ 32 000 cancers du poumon)</td></tr>\n          <tr><td>Maladies cardiovasculaires</td><td><span class=\"kw-chiffre\">≈ 17 000</span> (environ 1/4)</td></tr>\n          <tr><td>Maladies respiratoires</td><td><span class=\"kw-chiffre\">≈ 12 000</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"75-15","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’impact sur la mortalité cardiovasculaire","contenu":"<p>Le <span class=\"kw-etio\">tabac</span> multiplie par <span class=\"kw-chiffre\">≈ 20</span> le risque de développer une maladie cardiovasculaire. Il est la <strong>1ʳᵉ cause de maladie cardiovasculaire évitable</strong> et le <strong>1ᵉʳ <span class=\"kw-def\">facteur de risque</span> cardiovasculaire de la femme non ménopausée</strong>.</p>\n      <ul>\n        <li>Le <span class=\"kw-etio\">tabac</span> est responsable d'environ <span class=\"kw-chiffre\">10 %</span> des affections cardiovasculaires.</li>\n        <li>Effet plus marqué chez <span class=\"kw-clinique\">les</span> <strong>femmes</strong>, les <strong>hommes jeunes</strong> et les <strong>grands fumeurs</strong>.</li>\n        <li>L'association <span class=\"kw-ci\">tabac + contraception œstroprogestative</span> majore le risque thromboembolique.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Pathologie</th><th>Sur-risque</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Infarctus du myocarde</span></td><td>RR ≈ 3 — <strong>2ᵉ FR d'<span class=\"kw-etio\">IDM</span> après la <span class=\"kw-etio\">dyslipidémie</span></strong> ; effet-dose, pas de dose-seuil</td></tr>\n          <tr><td><span class=\"kw-alerte\">AOMI</span></td><td>RR ≈ 2-7 — <strong><span class=\"kw-chiffre\">90 %</span> des patients sont fumeurs</strong></td></tr>\n          <tr><td><span class=\"kw-etio\">AVC</span></td><td>RR ≈ 1,5-2</td></tr>\n          <tr><td>Autres</td><td>Anévrisme de l'aorte abdominale ; <span class=\"kw-etio\">HTA</span> ; cardiopathie hypertensive</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 222 — FDR cardiovasculaire · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-etio\">AVC</span></em></p>","frequence":1},{"id":"75-16","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie du tabagisme et celles des principales maladies liées au tabac","contenu":"<p>Le <span class=\"kw-etio\">tabagisme</span> touche <span class=\"kw-chiffre\">≈ 15 millions</span> de personnes en France (<span class=\"kw-chiffre\">33 %</span> des <span class=\"kw-chiffre\">18-75 ans</span>), dont <span class=\"kw-chiffre\">≈ 12 millions</span> de fumeurs quotidiens. Cette <span class=\"kw-def\">prévalence</span> se traduit par trois grandes familles de maladies attribuables :</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Poids attribuable au <span class=\"kw-etio\">tabac</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Cancers</span></td><td><span class=\"kw-chiffre\">≈ 25 %</span> des cancers ; le <span class=\"kw-etio\">tabac</span> est le 1ᵉʳ FR évitable de cancer</td></tr>\n          <tr><td>Maladies <strong>cardiovasculaires</strong></td><td><span class=\"kw-chiffre\">≈ 10 %</span> des affections <span class=\"kw-bio\">CV</span> ; risque <span class=\"kw-bio\">CV</span> ×20</td></tr>\n          <tr><td>Maladies <strong>respiratoires</strong></td><td><span class=\"kw-etio\">BPCO</span>, emphysème, bronchite chronique ; <span class=\"kw-etio\">asthme</span> aggravé</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon · 209 — <span class=\"kw-etio\">BPCO</span></em></p>","frequence":0},{"id":"75-17","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie du tabagisme passif, les grandes notions de sur-risque","contenu":"<p>Le <span class=\"kw-etio\">tabagisme passif</span> (involontaire) augmente le risque de maladie <strong>même à faibles doses</strong> — il n'existe pas de seuil sans risque.</p>\n      <table >\n        <thead><tr><th>Population</th><th>Sur-risque</th></tr></thead>\n        <tbody>\n          <tr><td>Adulte — cancer pulmonaire</td><td>RR augmenté de <span class=\"kw-chiffre\">≈ 25 %</span></td></tr>\n          <tr><td>Adulte — décès cardiovasculaire</td><td>RR augmenté de <span class=\"kw-chiffre\">≈ 20-30 %</span></td></tr>\n          <tr><td>Enfant / nourrisson</td><td>Infections <strong>ORL</strong> (<span class=\"kw-clinique\">otite</span>) ; infections <strong>pulmonaires</strong> (bronchite) ; <span class=\"kw-etio\">asthme</span> ; <span class=\"kw-alerte\">mort subite du nourrisson</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"75-18","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les catégories socio-professionnelles (CSP) des fumeurs en France","contenu":"<p>Le <span class=\"kw-etio\">tabac</span> reste un puissant <strong>marqueur social</strong>.</p>\n      <ul>\n        <li><span class=\"kw-def\">Prévalence</span> plus élevée chez <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">chômeurs</span>.</li>\n        <li>En 2018 : plus le revenu augmente, plus la <span class=\"kw-def\">prévalence</span> du <span class=\"kw-etio\">tabagisme</span> quotidien est <strong>basse</strong> (gradient social inverse).</li>\n        <li>La <span class=\"kw-def\">prévalence</span> diminue néanmoins, y compris parmi <span class=\"kw-clinique\">les</span> fumeurs les plus défavorisés.</li>\n      </ul>","frequence":0},{"id":"75-19","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir dépister la consommation de tabac","contenu":"<p>Tout patient doit faire l'objet, de manière <strong>systématique</strong>, d'une évaluation et d'un <span class=\"kw-def\">suivi</span> de sa consommation de <span class=\"kw-etio\">tabac</span>. Le <span class=\"kw-def\">dépistage</span> repose sur une question simple : « <strong>Fumez-vous ?</strong> »</p>\n      <p>La consommation se caractérise ensuite par le <strong>mode</strong> (avec ses équivalences), l'<strong>âge de début</strong>, la <strong>durée</strong> et la <strong>quantité</strong> :</p>\n      <table >\n        <thead><tr><th>Équivalence (en c<span class=\"kw-chiffre\">iga</span>rettes manufacturées)</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr><td>1 c<span class=\"kw-chiffre\">iga</span>rette roulée</td><td><span class=\"kw-chiffre\">2 cigarettes</span></td></tr>\n          <tr><td>1 c<span class=\"kw-chiffre\">iga</span>rillo</td><td><span class=\"kw-chiffre\">4 cigarettes</span></td></tr>\n          <tr><td>1 joint de cannabis</td><td><span class=\"kw-chiffre\">4 cigarettes</span></td></tr>\n          <tr><td>1 chicha</td><td><span class=\"kw-chiffre\">40 cigarettes</span></td></tr>\n        </tbody>\n      </table>\n      <p>La quantité s'exprime en <span class=\"kw-def\">paquets-années</span> : nombre de paquets/jour × nombre d'années de <span class=\"kw-etio\">tabagisme</span>.</p>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Le paquet-année n'est <strong>pas un bon évaluateur</strong> du risque : la <span class=\"kw-alerte\">quantité</span> augmente le risque de cancer avec un facteur puissance 2, mais la <span class=\"kw-alerte\">durée d'exposition</span> avec un facteur puissance 4 — la durée pèse beaucoup plus que la dose.\n      </div>","frequence":1},{"id":"75-20","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic de la dépendance","contenu":"<p>Le diagnostic de dépendance distingue trois registres. Environ <span class=\"kw-chiffre\">50 %</span> des fumeurs réguliers présentent des signes de dépendance.</p>\n      <table >\n        <thead><tr><th>Registre</th><th>Outil de diagnostic</th></tr></thead>\n        <tbody>\n          <tr><td>Dépendance <strong>pharmacologique</strong></td><td><span class=\"kw-def\">Test de Fagerström</span> (<span class=\"kw-clinique\">les</span> 4 premières questions sont les plus utiles)</td></tr>\n          <tr><td>Dépendance <strong>psychologique</strong> et <strong>comportementale</strong></td><td>Présence de <span class=\"kw-clinique\">craving</span> (= <span class=\"kw-alerte\">facteur de risque de rechute</span>)</td></tr>\n        </tbody>\n      </table>\n      <p>Le <strong>test de Fagerström</strong> existe en version complète (6 questions, <span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">0-10</span>) et en <strong>version simplifiée</strong> (2 questions — <span class=\"kw-clinique\">les</span> plus discriminantes) :</p>\n      <table >\n        <thead><tr><th>Question (version simplifiée)</th><th>Cotation</th></tr></thead>\n        <tbody>\n          <tr><td>Nombre de c<span class=\"kw-chiffre\">iga</span>rettes / jour</td><td><span class=\"kw-chiffre\">≤ 10</span> → 0 ; 11-20 → 1 ; 21-30 → 2 ; ≥ 31 → 3</td></tr>\n          <tr><td>Délai entre le réveil et la 1ʳᵉ c<span class=\"kw-chiffre\">iga</span>rette</td><td><span class=\"kw-chiffre\">≤ 5 min</span> → 3 ; <span class=\"kw-chiffre\">6-30 min</span> → 2 ; <span class=\"kw-chiffre\">31-60 min</span> → 1 ; &gt; <span class=\"kw-chiffre\">60 min</span> → 0</td></tr>\n        </tbody>\n      </table>\n      <p>Interprétation (version simplifiée) : <span class=\"kw-chiffre\">0-1</span> non dépendant · <span class=\"kw-chiffre\">2-3</span> dépendance modérée · <span class=\"kw-chiffre\">4-6</span> dépendance forte.</p>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Chez un patient <strong>dépendant</strong>, un traitement <span class=\"kw-ttt\">médicamenteux</span> est recommandé pour l'aide à l'arrêt.\n      </div>","frequence":3},{"id":"75-21","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes de sevrage en tabac","contenu":"<p>Le <span class=\"kw-def\">syndrome de sevrage</span> est consécutif au manque de <span class=\"kw-ttt\">nicotine</span>. Il apparaît <strong>rapidement</strong> après un arrêt brutal ou une diminution significative de la quantité fumée, et constitue le <span class=\"kw-alerte\">facteur de rechute principal</span>.</p>\n      <table >\n        <thead><tr><th>Domaine</th><th>Signes</th></tr></thead>\n        <tbody>\n          <tr><td>Humeur</td><td><span class=\"kw-clinique\">Humeur dépressive</span> ; irritabilité ; frustration ; colère</td></tr>\n          <tr><td>Sommeil</td><td><span class=\"kw-clinique\">Insomnie</span></td></tr>\n          <tr><td>Cognitif</td><td><span class=\"kw-clinique\">Anxiété</span> ; difficultés de concentration</td></tr>\n          <tr><td>Appétit / poids</td><td>Augmentation de l'appétit ; <span class=\"kw-clinique\">prise de poids</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"75-22","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications médicales non psychiatriques","contenu":"<p><span class=\"kw-clinique\">Les</span> complications non psychiatriques du <span class=\"kw-etio\">tabac</span> sont multi-systémiques. <strong>Cancers</strong> — le <span class=\"kw-etio\">tabac</span> est responsable de <span class=\"kw-chiffre\">≈ 25 %</span> des cancers :</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Précisions</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-alerte\">Cancer du poumon</span></td><td><span class=\"kw-chiffre\">90 %</span> des cancers du poumon sont liés au <span class=\"kw-etio\">tabac</span> ; un fumeur a 10-15× plus de risque qu'un non-fumeur ; le risque augmente dès la 1ʳᵉ c<span class=\"kw-chiffre\">iga</span>rette et décroît après l'arrêt sans revenir au niveau du non-fumeur</td></tr>\n          <tr><td>Cancers ORL / VADS</td><td>Cavités nasales, bouche, pharynx, larynx</td></tr>\n          <tr><td>Cancers digestifs</td><td>Œsophage (épidermoïde), estomac, foie, pancréas, côlon-rectum</td></tr>\n          <tr><td>Cancers urologiques</td><td>Rein, vessie</td></tr>\n          <tr><td>Cancers gynécologiques</td><td>Sein, ovaire, col de l'utérus</td></tr>\n          <tr><td>Hématologique</td><td>Leucémies myéloïdes (via le benzène)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique — cancers NON liés au <span class=\"kw-etio\">tabac</span>.</strong> Bons distracteurs QCM : cancer de la <span class=\"kw-alerte\">prostate</span> ; cancer du <span class=\"kw-alerte\">testicule</span> ; cancer de l'<span class=\"kw-alerte\">endomètre</span> ; cholangiocarcinome ; UCNT (rhinopharynx) ; cancer de l'<span class=\"kw-alerte\">ethmoïde</span> ; toutes <span class=\"kw-clinique\">les</span> tumeurs des glandes salivaires sauf la tumeur de Warthin ; cancers cutanés sauf le <span class=\"kw-clinique\">carcinome</span> épidermoïde.\n      </div>\n      <p><strong>Atteintes d'organes</strong> :</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr><td>Cardiovasculaire</td><td><span class=\"kw-etio\">IDM</span> ; AOMI ; <span class=\"kw-etio\">AVC</span> ; anévrisme de l'aorte abdominale ; <span class=\"kw-etio\">HTA</span></td></tr>\n          <tr><td>Respiratoire</td><td><span class=\"kw-etio\">BPCO</span> (évolue vers l'<span class=\"kw-ci\">insuffisance respiratoire</span> sans <span class=\"kw-ttt\">sevrage</span>) ; emphysème ; bronchite chronique ; <span class=\"kw-etio\">asthme</span> (exacerbations, mauvais contrôle)</td></tr>\n          <tr><td><span class=\"kw-ci\">Grossesse</span></td><td>Fausse couche ; mort fœtale in utero ; <span class=\"kw-alerte\">rupture</span> prématurée des membranes ; accouchement prématuré ; RCIU ; GEU ; placenta praevia ; hématome rétroplacentaire</td></tr>\n          <tr><td>Dermatologie</td><td>Vieillissement cutané accéléré ; coloration des ongles ; sécheresse cutanée ; aggravation de l'acné ; maladie de Buerger</td></tr>\n          <tr><td>Dents</td><td>Colorations dentaires ; <span class=\"kw-clinique\">parodontopathie</span> ; déchaussement dentaire</td></tr>\n          <tr><td><span class=\"kw-bio\">NFS</span></td><td>Polyglobulie ; polynucléose</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège — pathologies où le <span class=\"kw-etio\">tabac</span> est « protecteur ».</strong> Bons distracteurs : cancer de l'endomètre, pré-éclampsie, maladie de Parkinson, maladie d'Alzheimer, <span class=\"kw-clinique\">sarcoïdose</span>, pneumopathie d'<span class=\"kw-ci\">hypersensibilité</span>, <span class=\"kw-def\">rectocolite <span class=\"kw-etio\">hémorragique</span></span>. Il serait <strong>absurde</strong> de conseiller le <span class=\"kw-etio\">tabac</span> : <span class=\"kw-clinique\">les</span> risques dépassent largement ces rares « bénéfices ».\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 309 — Tumeurs du poumon · 209 — <span class=\"kw-etio\">BPCO</span> · 188 — <span class=\"kw-etio\">Asthme</span> - Rhinite · 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 340 — <span class=\"kw-etio\">AVC</span> · 225 — Artériopathie oblitérante - anévrysme</em></p>","frequence":0},{"id":"75-23","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître le diagnostic des comorbidités psychiatriques et addictives","contenu":"<p><strong><span class=\"kw-def\">Comorbidités</span> psychiatriques</strong> — beaucoup de patients atteints de troubles psychiatriques fument :</p>\n      <table >\n        <thead><tr><th>Trouble</th><th>Lien avec le <span class=\"kw-etio\">tabac</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Schizophrénie</span></td><td><span class=\"kw-chiffre\">82 %</span> de fumeurs</td></tr>\n          <tr><td><span class=\"kw-etio\">Trouble bipolaire</span></td><td><span class=\"kw-chiffre\">56 %</span> de fumeurs</td></tr>\n          <tr><td>Trouble panique</td><td>Le <span class=\"kw-etio\">tabac</span> pourrait le <strong>favoriser</strong> en raison de ses effets stimulants</td></tr>\n        </tbody>\n      </table>\n      <p>Avant un <span class=\"kw-ttt\">sevrage</span>, il faut <strong>repérer l'anxiété et l'<span class=\"kw-etio\">épisode dépressif caractérisé</span></strong>, actuels et sur la vie entière — <span class=\"kw-clinique\">les</span> fumeurs en difficulté pour arrêter sont susceptibles de manifester une humeur dépressive.</p>\n      <p><strong><span class=\"kw-def\">Comorbidités</span> addictives</strong> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Cannabis</span> : <span class=\"kw-alerte\">empêche l'arrêt du tabac</span>.</li>\n        <li><span class=\"kw-etio\">Alcool</span> : <span class=\"kw-def\">facteur de risque</span> de rechute ; sa prise est un stimulus déclencheur de l'envie de fumer.</li>\n        <li><span class=\"kw-etio\">Héroïne, cocaïne, méthamphétamine</span> : nécessitent une prise en charge spécialisée.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 77 — Addiction aux psychotropes · 78 — Addication aux drogues · 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble anxieux</em></p>","frequence":0},{"id":"75-24","rang":"A","rubrique":"Prise en charge","titre":"Moment du sevrage : connaître la proposition d'aide à l'arrêt à chaque contact avec un professionnel de santé","contenu":"<p>Le <span class=\"kw-def\">conseil minimal</span> doit être pratiqué par <strong>tous</strong> <span class=\"kw-clinique\">les</span> professionnels de santé, à <strong>chaque</strong> consultation, selon les <span class=\"kw-def\">5 A</span> :</p>\n      <table >\n        <thead><tr><th>Étape</th><th>Action</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Ask</strong></td><td>Demander à la personne si elle fume</td></tr>\n          <tr><td><strong>Assess</strong></td><td>Évaluer son <span class=\"kw-etio\">tabagisme</span></td></tr>\n          <tr><td><strong>Advise</strong></td><td>Conseiller à chaque fumeur d'arrêter de fumer</td></tr>\n          <tr><td><strong>Assist</strong></td><td>Évoquer la palette des aides et accompagnements disponibles</td></tr>\n          <tr><td><strong>Arrange</strong></td><td>Proposer un support écrit d'information pour appuyer ce conseil</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir — <span class=\"kw-ttt\">sevrage</span> rapide à envisager.</strong> Trois situations imposent d'envisager un <span class=\"kw-ttt\">sevrage tabagique</span> rapide : <span class=\"kw-alerte\">grossesse</span> ; <span class=\"kw-alerte\">découverte d'une maladie liée au tabac</span> ; <span class=\"kw-alerte\">chirurgie programmée</span> (un arrêt <span class=\"kw-chiffre\">6-8 semaines</span> avant diminue la morbi-<span class=\"kw-def\">mortalité</span> opératoire).\n      </div>","frequence":1},{"id":"75-25","rang":"A","rubrique":"Prise en charge","titre":"Connaître les moyens de prévention primaire et secondaire","contenu":"<p><span class=\"kw-clinique\">Les</span> mesures dont l'efficacité a été <strong>universellement vérifiée</strong> :</p>\n      <ul>\n        <li>Augmentation <strong>forte et régulièrement répétée</strong> des prix (1 paquet ≈ <span class=\"kw-chiffre\">10 €</span> en 2020).</li>\n        <li><span class=\"kw-ci\">Interdiction de la publicité</span>, directe et indirecte.</li>\n        <li>Interdiction de fumer dans <span class=\"kw-clinique\">les</span> <strong>lieux publics clos</strong> et les lieux de travail.</li>\n        <li><span class=\"kw-ci\">Interdiction de la vente de tabac aux moins de 18 ans</span>.</li>\n        <li>Apposition d'<strong>avertissements sanitaires illustrés</strong> sur <span class=\"kw-clinique\">les</span> paquets.</li>\n      </ul>\n      <table >\n        <thead><tr><th>Cadre</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td>Loi Veil (1976), loi Evin (1991), décret Bertrand (2006)</td><td>Interdiction de la publicité ; hausse des prix ; protection contre le <span class=\"kw-etio\">tabagisme passif</span> ; avertissements sanitaires ; interdiction de vente aux &lt;<span class=\"kw-chiffre\"> 18 ans</span></td></tr>\n          <tr><td><span class=\"kw-def\">PNRT</span> 2014-2019</td><td>Programme national de <span class=\"kw-ttt\">réduction</span> du <span class=\"kw-etio\">tabagisme</span> : <strong>paquet neutre</strong> ; remboursement des <span class=\"kw-ttt\">substituts nicotiniques</span> et de la varénicline ; opération « <strong>Mois sans <span class=\"kw-etio\">tabac</span></strong> »</td></tr>\n          <tr><td><span class=\"kw-def\">PNRT</span> 2018-2022</td><td>Protéger <span class=\"kw-clinique\">les</span> enfants de l'entrée dans le <span class=\"kw-etio\">tabagisme</span> ; accompagner les fumeurs vers le <span class=\"kw-ttt\">sevrage</span> ; agir sur l'économie du <span class=\"kw-etio\">tabac</span> ; <strong>objectif : 1ʳᵉ génération sans <span class=\"kw-etio\">tabac</span> d'ici 2032</strong> (&lt; <span class=\"kw-chiffre\">5 %</span> de fumeurs)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 60 — FdR, prévention, <span class=\"kw-def\">dépistage</span> des troubles psychiques</em></p>","frequence":0},{"id":"75-26","rang":"A","rubrique":"Prise en charge","titre":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","contenu":"<p>La prise en charge associe des moyens <strong>non pharmacologiques</strong> et <strong>pharmacologiques</strong>.</p>\n      <table >\n        <thead><tr><th>Moyen</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Conseil minimal</td><td>Pratiqué par tout professionnel de santé, à chaque consultation (5 A)</td></tr>\n          <tr><td>Psychothérapie</td><td><span class=\"kw-ttt\">Entretien motivationnel</span> ; psychothérapie de soutien ; <span class=\"kw-ttt\">thérapies cognitivo-comportementales</span> (même efficacité que <span class=\"kw-clinique\">les</span> médicaments)</td></tr>\n          <tr><td>Aides</td><td>Accompagnement téléphonique (<strong><span class=\"kw-etio\">Tabac</span> Info Service</strong>) ; consultation de tabacologie</td></tr>\n          <tr><td>Substitution</td><td><span class=\"kw-ttt\">Substituts nicotiniques</span> en <strong>1ʳᵉ intention</strong> ; c<span class=\"kw-chiffre\">iga</span>rette électronique</td></tr>\n          <tr><td>Médicaments</td><td><span class=\"kw-ttt\">Varénicline</span> en 2ⁿᵈ intention ; <span class=\"kw-ttt\">bupropion</span> en dernière intention</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ttt\">Substituts nicotiniques</span></strong> (1ʳᵉ intention) — réduisent l'envie de fumer et <span class=\"kw-clinique\">les</span> symptômes de manque :</p>\n      <ul>\n        <li><strong>Formes :</strong> transdermiques (timbres / patchs, <span class=\"kw-chiffre\">16 h</span> ou <span class=\"kw-chiffre\">24 h</span>) ; orales (gommes, comprimés, pastilles, inhaleurs, sprays) — associables entre elles.</li>\n        <li><strong>Dose :</strong> 1 c<span class=\"kw-chiffre\">iga</span>rette ≈ <span class=\"kw-chiffre\">1 mg</span> (≈ <span class=\"kw-chiffre\">20 mg</span>/j pour 1 paquet/j), à adapter aux signes de sur/sous-dosage ; diminution progressive sur <span class=\"kw-chiffre\">≥ 3 mois</span>.</li>\n        <li><strong>Efficacité :</strong> à <span class=\"kw-chiffre\">6 mois</span>, <span class=\"kw-chiffre\">2-3×</span> plus d'arrêts ; <span class=\"kw-ci\">aucune contre-indication</span> (prudence pendant la <span class=\"kw-ci\">grossesse</span> et en cas de pathologie cardiovasculaire).</li>\n        <li><strong>EI :</strong> modérés et régressifs (<span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">palpitations</span> ; <span class=\"kw-clinique\">érythème</span>/<span class=\"kw-clinique\">prurit</span> au point d'application ; troubles buccaux des formes orales).</li>\n        <li><strong>Remboursement :</strong> <span class=\"kw-chiffre\">65 %</span> (<span class=\"kw-chiffre\">100 %</span> si <span class=\"kw-def\">ALD</span>), <strong>sauf inhaleur et spray</strong>.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le détail de la <span class=\"kw-ttt\">varénicline</span> et du <span class=\"kw-ttt\">bupropion</span> (aide médicamenteuse autre que <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">substituts nicotiniques</span>) est développé dans l'objectif dédié.\n      </div>","frequence":4},{"id":"75-27","rang":"A","rubrique":"Prise en charge","titre":"Connaître les outils institutionnels (tabac info service)","contenu":"<ul>\n        <li><strong><span class=\"kw-etio\">Tabac</span> Info Service</strong> : ligne d'<span class=\"kw-ttt\">accompagnement téléphonique</span> à l'arrêt du <span class=\"kw-etio\">tabac</span>.</li>\n        <li><strong>Consultation de tabacologie</strong> : destinée aux personnes ayant des difficultés à arrêter de consommer du <span class=\"kw-etio\">tabac</span>.</li>\n        <li><strong>Forfait d'aide au <span class=\"kw-ttt\">sevrage</span></strong> : porté à <span class=\"kw-chiffre\">150 € / an</span> pour tous <span class=\"kw-clinique\">les</span> assurés.</li>\n      </ul>","frequence":1},{"id":"75-28","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la prise en charge après un évènement aigu : infarctus du myocarde, décompensation respiratoire…","contenu":"<p>La survenue d'un <strong>événement aigu lié au <span class=\"kw-etio\">tabac</span></strong> est un moment clé pour proposer le <span class=\"kw-ttt\">sevrage</span> : la <span class=\"kw-alerte\">découverte d'une maladie liée au tabac</span> fait partie des situations imposant d'envisager un <span class=\"kw-ttt\">sevrage</span> rapide.</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Infarctus du myocarde</span> : le <span class=\"kw-ttt\">sevrage</span> diminue rapidement le risque <span class=\"kw-etio\">ischémique</span> (abaissement des 2/3 du surcroît de risque dès la 1ʳᵉ année, retour quasiment au risque de base après la 3ᵉ année).</li>\n        <li><span class=\"kw-alerte\">Décompensation respiratoire</span> : le <span class=\"kw-ttt\">sevrage</span> est impératif, la <span class=\"kw-etio\">BPCO</span> évoluant vers l'<span class=\"kw-ci\">insuffisance respiratoire</span> en l'absence d'arrêt.</li>\n        <li><strong><span class=\"kw-ttt\">Chirurgie</span> programmée</strong> : un arrêt préalable <span class=\"kw-chiffre\">6-8 semaines</span> avant l'intervention diminue la morbi-<span class=\"kw-def\">mortalité</span> opératoire.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> <span class=\"kw-clinique\">Les</span> modalités fines de la prise en charge du <span class=\"kw-ttt\">sevrage</span> après un événement aigu sont peu détaillées dans la fiche source du dossier <code>75-addiction-<span class=\"kw-etio\">tabac</span>/</code> — Kevin pourra enrichir ce paragraphe depuis le Collège.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — <span class=\"kw-clinique\">Syndrome coronarien</span> aiguë · 209 — <span class=\"kw-etio\">BPCO</span></em></p>","frequence":0},{"id":"75-29","rang":"B","rubrique":"Prise en charge","titre":"Savoir rechercher des comorbidités en fonction du terrain","contenu":"<p>Avant et pendant la prise en charge, rechercher systématiquement <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">comorbidités</span> selon le terrain :</p>\n      <table >\n        <thead><tr><th>Type</th><th>À rechercher</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Comorbidités</span> <strong>addictives</strong></td><td><span class=\"kw-etio\">Cannabis</span> (empêche l'arrêt du <span class=\"kw-etio\">tabac</span>) ; <span class=\"kw-etio\">alcool</span> (FR de rechute, stimulus déclencheur) ; héroïne, cocaïne, méthamphétamine (PEC spécialisée)</td></tr>\n          <tr><td><span class=\"kw-def\">Comorbidités</span> <strong>psychiatriques</strong></td><td><span class=\"kw-clinique\">Anxiété</span> et <span class=\"kw-etio\">épisode dépressif caractérisé</span>, actuels et sur la vie entière, à repérer avant un <span class=\"kw-ttt\">sevrage</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> La fiche source du dossier <code>75-addiction-<span class=\"kw-etio\">tabac</span>/</code> ne dédie pas de section à la recherche de <span class=\"kw-def\">comorbidités</span> « selon le terrain » : ce body recoupe <span class=\"kw-clinique\">les</span> notions existantes — Kevin pourra l'enrichir depuis le Collège.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 78 — Addication aux drogues</em></p>","frequence":0},{"id":"75-30","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la prise en charge à long terme : savoir que les rechutes sont la règle d'où la proposition systématique de l'arrêt du tabac","contenu":"<p>Le <span class=\"kw-def\">suivi</span> à long terme permet le maintien de l'arrêt, l'adaptation du traitement, la surveillance de l'état psychique et des autres consommations.</p>\n      <table >\n        <thead><tr><th>Élément</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td>Durée du <span class=\"kw-def\">suivi</span></td><td><span class=\"kw-chiffre\">≈ 6-12 mois</span> ; périodicité définie avec le fumeur</td></tr>\n          <tr><td><span class=\"kw-ttt\">Sevrage</span> « réussi »</td><td><span class=\"kw-ttt\">Sevrage</span> total sur une durée <span class=\"kw-chiffre\">≥ 1 an</span></td></tr>\n          <tr><td>Facteurs prédictifs d'arrêt</td><td>Âge de début tardif ; bon niveau socio-économique ; entourage non fumeur ; durée d'intoxication brève ; faible consommation ; long délai éveil-1ʳᵉ c<span class=\"kw-chiffre\">iga</span>rette ; forte motivation</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">rechutes sont la règle</span> : la rechute doit être <strong>dédramatisée</strong>, elle constitue une étape souvent nécessaire de l'apprentissage de la vie sans <span class=\"kw-etio\">tabac</span> (en moyenne <span class=\"kw-chiffre\">5 tentatives d'arrêt</span> avant le <span class=\"kw-ttt\">sevrage</span> définitif). D'où la <strong>proposition systématique de l'arrêt du <span class=\"kw-etio\">tabac</span></strong> à chaque <span class=\"kw-def\">contact</span>.\n      </div>","frequence":1},{"id":"75-31","rang":"B","rubrique":"Prise en charge","titre":"Connaître l’aide médicamenteuse autre que traitements substitutifs nicotiniques","contenu":"<p>En <span class=\"kw-bio\">complément</span> des <span class=\"kw-ttt\">substituts nicotiniques</span> (1ʳᵉ intention), deux médicaments spécifiques peuvent être utilisés.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Varénicline</th><th>Bupropion</th></tr></thead>\n        <tbody>\n          <tr><td>Classe</td><td><span class=\"kw-ttt\">Agoniste partiel</span> des récepteurs nicotiniques à l'acétylcholine</td><td><span class=\"kw-ttt\">Inhibiteur de la recapture</span> de la <span class=\"kw-ttt\">noradrénaline</span> et de la <span class=\"kw-ttt\">dopamine</span></td></tr>\n          <tr><td>Action</td><td>Réduit <span class=\"kw-clinique\">les</span> symptômes de manque ; bloque l'effet satisfaisant de la nicotine inhalée</td><td>Réduit l'envie de fumer et <span class=\"kw-clinique\">les</span> symptômes de manque</td></tr>\n          <tr><td>Efficacité (à <span class=\"kw-chiffre\">6 mois</span>)</td><td>Chances d'arrêt <span class=\"kw-chiffre\">×3</span></td><td>Chances d'arrêt <span class=\"kw-chiffre\">×2</span></td></tr>\n          <tr><td>Indication</td><td><strong>2ⁿᵈ intention</strong>, si échec des <span class=\"kw-ttt\">substituts nicotiniques</span> et dépendance forte</td><td><strong>Dernière intention</strong></td></tr>\n          <tr><td>Effets indésirables</td><td><span class=\"kw-clinique\">Céphalées</span> ; troubles digestifs ; troubles du sommeil (cauchemars, insomnie) ; <span class=\"kw-alerte\">risque cardiovasculaire</span> ; <span class=\"kw-alerte\">dépression, idées et comportements suicidaires</span>, agitation</td><td>Réactions cutanées ; insomnie, angoisse ; <span class=\"kw-alerte\">convulsions</span> ; <span class=\"kw-etio\">HTA</span>, <span class=\"kw-clinique\">angor</span>, <span class=\"kw-etio\">IDM</span> ; <span class=\"kw-alerte\">idées suicidaires</span> ; <span class=\"kw-clinique\">céphalées</span></td></tr>\n          <tr><td>Remboursement</td><td><span class=\"kw-chiffre\">65 %</span> par l'Assurance maladie</td><td><span class=\"kw-ci\">Non remboursé</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"75-32","rang":"B","rubrique":"Prise en charge","titre":"Savoir quand adresser un patient en consultation de tabacologie","contenu":"<p>La <strong>consultation de tabacologie</strong> s'adresse aux personnes ayant des <span class=\"kw-alerte\">difficultés à arrêter</span> de consommer du <span class=\"kw-etio\">tabac</span>. Sont notamment concernés :</p>\n      <ul>\n        <li><span class=\"kw-alerte\">Échecs répétés</span> des tentatives d'arrêt.</li>\n        <li><span class=\"kw-alerte\">Dépendance forte</span> à la nicotine (<span class=\"kw-def\">score</span> de Fagerström élevé).</li>\n        <li><span class=\"kw-clinique\">Comorbidités psychiatriques</span> ou <span class=\"kw-clinique\">addictives</span> associées.</li>\n        <li><span class=\"kw-def\">Terrain</span> à risque ou demande spécifique du patient.</li>\n      </ul>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> pas d'<span class=\"kw-alerte\">urgence vitale</span>, mais l'aide à l'arrêt doit être <span class=\"kw-ttt\">proposée à chaque contact</span> avec un professionnel de santé<br><strong><span class=\"kw-ttt\">Sevrage</span> rapide impératif si :</strong> <span class=\"kw-alerte\">grossesse</span>, <span class=\"kw-alerte\">découverte d'une maladie liée au tabac</span>, <span class=\"kw-alerte\">chirurgie programmée</span><br><strong>Délai pré-opératoire :</strong> arrêt <span class=\"kw-chiffre\">6-8 semaines</span> avant la <span class=\"kw-ttt\">chirurgie</span> (diminue la morbi-<span class=\"kw-def\">mortalité</span> opératoire)<br><strong>1er geste :</strong> <span class=\"kw-ttt\">conseil minimal</span> (5A) + proposition d'aide à l'arrêt</p>","hospit":"<p><strong>Cadre :</strong> prise en charge <span class=\"kw-ttt\">ambulatoire</span> dans la quasi-totalité des cas<br><strong>Initiation :</strong> tout professionnel de santé disposant d'un n° RPPS peut prescrire des <span class=\"kw-ttt\">substituts nicotiniques</span> (y compris <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">infirmières</span>)<br><strong>Adresser en consultation de tabacologie si :</strong> difficultés à arrêter, dépendance forte, <span class=\"kw-def\">comorbidités</span><br><strong>Aide à distance :</strong> ligne <span class=\"kw-ttt\">Tabac Info Service</span></p>","redflags":"<ul><li><span class=\"kw-alerte\">Dépendance forte au test de Fagerström</span> (<span class=\"kw-def\">score</span> <span class=\"kw-chiffre\">7-10</span>) : <span class=\"kw-ttt\">substituts nicotiniques</span> quasi indispensables</li><li><span class=\"kw-clinique\">Craving</span> : reflet de la dépendance psychologique, <span class=\"kw-alerte\">facteur de risque de rechute</span></li><li><span class=\"kw-etio\">Comorbidités psychiatriques</span> (anxiété, épisode dépressif caractérisé) à dépister avant tout <span class=\"kw-ttt\">sevrage</span></li><li>Co-consommations : <span class=\"kw-etio\">cannabis</span> (empêche l'arrêt du tabac) et <span class=\"kw-etio\">alcool</span> (FR de rechute, stimulus déclencheur de l'envie de fumer)</li><li><span class=\"kw-alerte\">Grossesse</span>, <span class=\"kw-alerte\">maladie liée au tabac</span> ou <span class=\"kw-alerte\">chirurgie programmée</span> : imposent un <span class=\"kw-ttt\">sevrage</span> rapide</li></ul>","principes":"<p>Proposition <span class=\"kw-ttt\">systématique</span> de l'arrêt à chaque <span class=\"kw-def\">contact</span> ; <span class=\"kw-ttt\">traitement médicamenteux</span> recommandé chez tout patient dépendant, toujours associé à un accompagnement.</p><p><strong>Accompagnement & conseil (socle)</strong></p><p>Accompagnement indispensable quel que soit le traitement <span class=\"kw-etio\">médicamenteux</span></p><ul><li><span class=\"kw-ttt\">Conseil minimal</span> par tout soignant, à chaque consultation, selon <span class=\"kw-clinique\">les</span> 5A (Ask, Assess, Advise, Assist, Arrange)</li><li><span class=\"kw-ttt\">Entretien motivationnel</span> centré sur le patient</li><li><span class=\"kw-ttt\">Thérapies cognitivo-comportementales</span> : même efficacité que <span class=\"kw-clinique\">les</span> médicaments</li></ul><p><strong><span class=\"kw-ttt\">Substituts nicotiniques</span> (1re intention)</strong></p><p>Aucune <span class=\"kw-ci\">contre-indication</span> ; utilisables pendant la <span class=\"kw-ci\">grossesse</span></p><ul><li>Formes transdermiques (<span class=\"kw-ttt\">patchs</span><span class=\"kw-chiffre\"> 24h</span>/<span class=\"kw-chiffre\">16h</span>) ± formes orales (<span class=\"kw-ttt\">gommes</span>, <span class=\"kw-ttt\">pastilles</span>, <span class=\"kw-ttt\">sprays</span>)</li><li>Dose : <span class=\"kw-chiffre\">1 cigarette ≈ 1 mg</span>, à adapter aux signes de sur/sous-dosage</li><li>Décroissance progressive sur une durée <span class=\"kw-chiffre\">≥ 3 mois</span></li><li><span class=\"kw-chiffre\">2 à 3x</span> plus d'arrêt à<span class=\"kw-chiffre\"> 6 mois</span> ; remboursés à <span class=\"kw-chiffre\">65%</span> (<span class=\"kw-chiffre\">100% en ALD</span>)</li></ul><p><strong>Médicaments de <span class=\"kw-chiffre\">2e intention</span></strong></p><p>Surveiller humeur et idées suicidaires (varénicline) ; <span class=\"kw-alerte\">convulsions</span> et <span class=\"kw-etio\">HTA</span> (bupropion)</p><ul><li><span class=\"kw-ttt\">Varénicline</span> : agoniste partiel des récepteurs nicotiniques, <span class=\"kw-chiffre\">x3</span> d'arrêt à<span class=\"kw-chiffre\"> 6 mois</span> — si <span class=\"kw-alerte\">échec des substituts</span> + dépendance forte</li><li><span class=\"kw-ttt\">Bupropion</span> : inhibiteur de recapture <span class=\"kw-ttt\">noradrénaline</span>/<span class=\"kw-ttt\">dopamine</span>, <span class=\"kw-chiffre\">x2</span> d'arrêt à<span class=\"kw-chiffre\"> 6 mois</span> — en dernière intention</li></ul><p><strong>Aides non pharmacologiques</strong></p><ul><li><span class=\"kw-ttt\">Cigarette électronique</span> : aide possible au <span class=\"kw-ttt\">sevrage</span> (absence de combustion, ni CO ni goudron)</li><li><span class=\"kw-ci\">Non recommandée chez la femme enceinte</span> ni chez le <span class=\"kw-ci\">non-fumeur</span></li><li>Ligne <span class=\"kw-ttt\">Tabac Info Service</span>, consultation de tabacologie</li></ul>","suivi":"<p><strong>Durée :</strong> <span class=\"kw-def\">suivi</span> sur <span class=\"kw-chiffre\">6-12 mois</span>, périodicité définie avec le fumeur<br><strong>Surveiller :</strong> maintien de l'abstinence, adaptation du traitement, état psychique, consommation d'autres substances psychoactives<br><strong><span class=\"kw-ttt\">Sevrage</span> réussi :</strong> abstinence totale <span class=\"kw-chiffre\">≥ 1 an</span><br><strong>Rechute :</strong> à dédramatiser, c'est la règle — <span class=\"kw-chiffre\">5 tentatives</span> en moyenne avant le <span class=\"kw-ttt\">sevrage</span> définitif, d'où la proposition systématique de l'arrêt</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient fumeur — Dépistage systématique « Fumez-vous ? » à chaque contact + conseil minimal (5A)","detail":"<h4>CAT — Aide à l'arrêt du tabac — Du <span class=\"kw-def\">dépistage</span> systématique au choix du traitement selon la dépendance</h4>","branches":[{"to":"t-rapide","label":"Grossesse / maladie liée au tabac / chirurgie programmée","color":"amber"},{"to":"q-dependance","label":"Sevrage programmé : évaluer","color":"green"}]},{"id":"t-rapide","kind":"terminal","label":"Sevrage rapide à organiser","color":"amber","detail":"<h4>Conduite</h4><ul><li>Organiser l'<span class=\"kw-ttt\">arrêt sans délai</span>, sans attendre une forte motivation</li><li><span class=\"kw-ttt\">Substituts nicotiniques</span> utilisables pendant la <span class=\"kw-alerte\">grossesse</span></li></ul><h4>Délai</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> programmée : arrêt <span class=\"kw-chiffre\">6-8 semaines</span> avant pour réduire la morbi-<span class=\"kw-def\">mortalité</span> opératoire</li></ul>"},{"id":"q-dependance","kind":"decision","label":"Dépendance évaluée par le test de Fagerström ?","branches":[{"to":"t-faible","label":"Score 0-2 (faible/nulle)","color":"green"},{"to":"q-sn","label":"Score ≥ 3 (dépendance ≥ modérée)","color":"amber"}]},{"id":"t-faible","kind":"terminal","label":"Arrêt sans substitut nicotinique","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-def\">Score</span> de Fagerström <span class=\"kw-chiffre\">0-2</span> : <span class=\"kw-def\">dépendance faible ou nulle</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Conseil d'arrêt</span> + accompagnement (<span class=\"kw-ttt\">entretien motivationnel</span>, <span class=\"kw-ttt\">TCC</span>)</li><li>Arrêt possible <span class=\"kw-ttt\">sans substitut nicotinique</span></li></ul>"},{"id":"q-sn","kind":"decision","label":"Substituts nicotiniques (1re intention) : efficaces ? — dose adaptée, durée ≥ 3 mois","branches":[{"to":"t-sn","label":"Arrêt obtenu","color":"green"},{"to":"q-2eintention","label":"Échec malgré bonne conduite","color":"amber"}]},{"id":"t-sn","kind":"terminal","label":"Arrêt obtenu sous substituts — suivi","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Substituts nicotiniques</span> en 1re intention : <span class=\"kw-chiffre\">2-3x</span> plus d'arrêt à<span class=\"kw-chiffre\"> 6 mois</span></li><li><span class=\"kw-ttt\">Patchs</span> transdermiques ± formes orales (<span class=\"kw-ttt\">gommes</span>, <span class=\"kw-ttt\">pastilles</span>, <span class=\"kw-ttt\">sprays</span>)</li><li>Décroissance progressive sur <span class=\"kw-chiffre\">≥ 3 mois</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Adapter la dose aux signes de <span class=\"kw-alerte\">surdosage</span> / sous-dosage</li><li>Remboursés à <span class=\"kw-chiffre\">65%</span> (<span class=\"kw-chiffre\">100% en ALD</span>)</li></ul>"},{"id":"q-2eintention","kind":"decision","label":"Traitement médicamenteux de 2e intention","branches":[{"to":"t-vareni","label":"En 2e intention","color":"amber"},{"to":"t-bupro","label":"Échec varénicline / dernière intention","color":"amber"}]},{"id":"t-vareni","kind":"terminal","label":"Varénicline (2e intention)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Varénicline</span> : agoniste partiel des récepteurs nicotiniques</li><li>Multiplie <span class=\"kw-chiffre\">x3</span> <span class=\"kw-clinique\">les</span> chances d'arrêt à<span class=\"kw-chiffre\"> 6 mois</span></li><li>Indication : <span class=\"kw-alerte\">échec des substituts</span> + dépendance forte</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Surveiller l'humeur : <span class=\"kw-alerte\">dépression</span>, <span class=\"kw-alerte\">idées suicidaires</span>, agitation</li><li>Remboursée à <span class=\"kw-chiffre\">65%</span></li></ul>"},{"id":"t-bupro","kind":"terminal","label":"Bupropion (dernière intention)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Bupropion</span> : inhibiteur de recapture <span class=\"kw-ttt\">noradrénaline</span>/<span class=\"kw-ttt\">dopamine</span></li><li>Multiplie <span class=\"kw-chiffre\">x2</span> <span class=\"kw-clinique\">les</span> chances d'arrêt à<span class=\"kw-chiffre\"> 6 mois</span></li><li>En <span class=\"kw-ttt\">dernière intention</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>EI : insomnie, <span class=\"kw-alerte\">convulsions</span>, <span class=\"kw-alerte\">HTA</span>, troubles psychiatriques</li><li>Non remboursé</li></ul>"}]},"cards":[{"i":"1aadca5bc4a9","n":75,"o":"75-1","u":"Définition","t":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","q":"Quels sont les principaux risques liés au tabagisme passif chez l'adulte et la femme enceinte ?","a":"<p>Les principaux risques liés au tabagisme passif sont :</p><ul><li>Chez l'adulte : <strong>cancer pulmonaire</strong> (risque relatif +25%), <strong>décès cardiovasculaire</strong> (risque relatif +20-30%). Le risque est présent même à faibles doses.</li><li>Chez la femme enceinte : <strong>retard de croissance intra-utérin (RCIU)</strong>, <strong>accouchement prématuré</strong>.</li></ul>"},{"i":"31e4a669e37b","n":75,"o":"75-1","u":"Définition","t":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","q":"Quels sont les principaux risques liés au tabagisme actif pour le fumeur ?","a":"<p>Les principaux risques liés au tabagisme actif incluent :</p><ul><li><strong>Cancers</strong> : poumon, voies aéro-digestives supérieures, vessie, pancréas.</li><li><strong>Pathologies cardiovasculaires</strong> : Hypertension artérielle (HTA), infarctus du myocarde (IDM), artériopathie oblitérante des membres inférieurs (AOMI), accidents vasculaires cérébraux (AVC).</li><li><strong>Pathologies respiratoires</strong> : Bronchopneumopathie chronique obstructive (BPCO), emphysème.</li><li><strong>Troubles de la reproduction</strong> : baisse de la fertilité, troubles de la grossesse.</li></ul>"},{"i":"5027edce21aa","n":75,"o":"75-1","u":"Définition","t":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","q":"Quelle est la particularité de la toxicité du courant secondaire de la fumée de cigarette par rapport au courant primaire ?","a":"<p>Le <strong>courant secondaire</strong> (fumée s'échappant du bout incandescent de la cigarette) est <strong>plus toxique</strong> que le courant primaire inhalé par le fumeur. Il est <strong>plus concentré en monoxyde de carbone, goudrons et cancérigènes</strong>, et n'est pas filtré.</p>"},{"i":"ce1c7adcd14c","n":75,"o":"75-1","u":"Définition","t":"Connaître les principaux risques liés au tabagisme actif, au tabagisme passif, et au tabagisme in utero","q":"Quels sont les principaux risques du tabagisme passif pour l'enfant et le nourrisson et du tabagisme in utero pour le fœtus ou la grossesse ?","a":"<p>Les principaux risques incluent :</p><ul><li>Pour l'enfant / nourrisson (tabagisme passif) : <strong>otites et infections ORL</strong>, <strong>infections pulmonaires</strong>, <strong>asthme</strong>, <strong>mort subite du nourrisson</strong>.</li><li>Pour le fœtus ou la grossesse (tabagisme in utero) : <strong>fausse couche</strong>, <strong>mort fœtale in utero</strong>, <strong>rupture prématurée des membranes</strong>, <strong>accouchement prématuré</strong>, <strong>retard de croissance intra-utérin (RCIU)</strong>, <strong>grossesse extra-utérine</strong>, <strong>placenta praevia</strong>, <strong>hématome rétroplacentaire</strong>.</li></ul>"},{"i":"1dd0bca7cd6d","n":75,"o":"75-10","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez la femme enceinte","q":"Quelles sont les caractéristiques sociodémographiques des femmes enceintes plus susceptibles de poursuivre leur tabagisme durant la grossesse ?","a":"<p>La poursuite du tabagisme est plus fréquente chez les femmes enceintes <strong>les plus jeunes</strong> et <strong>les moins diplômées</strong>.</p>"},{"i":"2df79b70d2f5","n":75,"o":"75-10","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez la femme enceinte","q":"Quelle est la proportion de femmes enceintes qui continuent de fumer pendant leur grossesse ?","a":"<p>Environ <strong>50 %</strong> des femmes enceintes continuent de fumer pendant leur grossesse.</p>"},{"i":"4c29f2ab0cb9","n":75,"o":"75-11","u":"Epidémiologie","t":"Connaître les modes de consommation du tabac","q":"Quels sont les produits du tabac consommés par ingestion et quelle est leur particularité réglementaire en Europe ?","a":"<p>Les produits du tabac consommés par ingestion sont :</p><ul><li>Le <strong>snus</strong> : tabac humide en sachet placé entre gencive et lèvre. Sa vente est <strong>interdite en Europe</strong>, à l'exception de la Suède.</li><li>Le <strong>tabac à chiquer</strong>.</li></ul>"},{"i":"61d00ca6c5e2","n":75,"o":"75-11","u":"Epidémiologie","t":"Connaître les modes de consommation du tabac","q":"Quels sont les principaux modes de consommation du tabac entraînant une inhalation après combustion complète ?","a":"<p>Les produits du tabac consommés par inhalation après combustion complète à haute température sont :</p><ul><li>La <strong>chicha</strong> (pipe à eau).</li><li>Les <strong>cigarettes</strong> manufacturées et roulées.</li><li>Les <strong>cigarillos</strong> et <strong>cigares</strong>.</li><li>La <strong>pipe</strong>.</li></ul>"},{"i":"9cb4297480bf","n":75,"o":"75-11","u":"Epidémiologie","t":"Connaître les modes de consommation du tabac","q":"Comment doit-on considérer les produits de tabac chauffé par rapport aux autres modes de consommation du tabac ?","a":"<p>Les <strong>produits de tabac chauffé</strong>, bien que résultant d'une combustion incomplète, doivent être considérés comme des <strong>cigarettes</strong> en termes de risques. Il ne faut pas les confondre avec la cigarette électronique.</p>"},{"i":"fe08ce719467","n":75,"o":"75-11","u":"Epidémiologie","t":"Connaître les modes de consommation du tabac","q":"Quels sont les modes de consommation du tabac impliquant une inhalation sans combustion ?","a":"<p>Les modes de consommation du tabac sans combustion incluent :</p><ul><li>La <strong>cigarette électronique</strong>.</li><li>Les <strong>puffs</strong> (cigarettes électroniques jetables).</li><li>Le <strong>tabac à priser</strong> (sniffé).</li></ul>"},{"i":"1107aebf39b6","n":75,"o":"75-12","u":"Epidémiologie","t":"Connaître l’ordre de grandeur du nombre de cas de cancer liés au tabac","q":"Quel est le nombre annuel de décès spécifiquement par cancer du poumon liés au tabac en France ?","a":"<p>Sur les décès par cancer liés au tabac, environ <strong>32 000</strong> sont des cancers du poumon.</p>"},{"i":"281a47584686","n":75,"o":"75-12","u":"Epidémiologie","t":"Connaître l’ordre de grandeur du nombre de cas de cancer liés au tabac","q":"Existe-t-il un seuil de consommation de tabac sans risque en termes de risque de cancer ?","a":"<p>Non, il n'existe <strong>pas de seuil de consommation sans risque</strong>. Même le tabagisme passif augmente le risque de cancer.</p>"},{"i":"5c819d8cfdc2","n":75,"o":"75-12","u":"Epidémiologie","t":"Connaître l’ordre de grandeur du nombre de cas de cancer liés au tabac","q":"Quel est le nombre annuel de décès par cancer liés au tabac en France ?","a":"<p>Le tabac est responsable d'environ <strong>46 000 à 46 500</strong> décès par cancer par an en France.</p>"},{"i":"c0115d2f6b53","n":75,"o":"75-12","u":"Epidémiologie","t":"Connaître l’ordre de grandeur du nombre de cas de cancer liés au tabac","q":"Quelle est la part des cancers attribuables au tabac au global en France ?","a":"<p>Environ <strong>25 %</strong> de tous les cancers sont attribuables au tabac en France.</p>"},{"i":"2475ceeacb38","n":75,"o":"75-13","u":"Epidémiologie","t":"Connaître la part du tabac dans la mortalité en France","q":"Quelle est la part du tabac dans les décès chez l'homme en France ?","a":"<p>La part du tabac dans l'ensemble des décès chez l'homme en France est de <strong>20 %</strong>.</p>"},{"i":"41af9936e874","n":75,"o":"75-13","u":"Epidémiologie","t":"Connaître la part du tabac dans la mortalité en France","q":"Quelle est la part du tabac dans les décès chez la femme en France ?","a":"<p>La part du tabac dans l'ensemble des décès chez la femme en France est de <strong>7 %</strong>.</p>"},{"i":"545dd40f70c2","n":75,"o":"75-13","u":"Epidémiologie","t":"Connaître la part du tabac dans la mortalité en France","q":"Quel est le nombre estimé de décès prématurés attribuables au tabac chaque année en France ?","a":"<p>On estime à environ <strong>75 000</strong> le nombre de décès prématurés annuels attribuables au tabac en France.</p>"},{"i":"6842163832ac","n":75,"o":"75-13","u":"Epidémiologie","t":"Connaître la part du tabac dans la mortalité en France","q":"Quel est le statut du tabac en matière de mortalité en France ?","a":"<p>Le tabac est la <strong>première cause de décès évitable</strong> en France.</p>"},{"i":"424584df5bc6","n":75,"o":"75-14","u":"Epidémiologie","t":"Connaître la mortalité liée au tabagisme actif","q":"Quelle est la proportion de fumeurs qui mourront prématurément d'une maladie liée au tabac ?","a":"<p>Environ <strong>un fumeur sur deux</strong> (soit <strong>50 %</strong>) mourra prématurément d'une maladie due au tabac.</p>"},{"i":"815c3473ad24","n":75,"o":"75-14","u":"Epidémiologie","t":"Connaître la mortalité liée au tabagisme actif","q":"Quelle cause spécifique de cancer est la plus fortement associée au tabagisme actif en termes de mortalité annuelle, et combien de décès lui sont attribués ?","a":"<p>La cause spécifique de cancer la plus fortement associée au tabagisme actif est le <strong>cancer du poumon</strong>, responsable d'environ <strong>32 000</strong> décès par an.</p>"},{"i":"e94f9ca10801","n":75,"o":"75-14","u":"Epidémiologie","t":"Connaître la mortalité liée au tabagisme actif","q":"Quelles sont les trois principales causes de décès prématuré liées au tabagisme actif, et leur mortalité annuelle respective en France selon les données de 2015 ?","a":"<ul><li><strong>Cancers</strong> : environ <strong>46 000</strong> décès par an.</li><li><strong>Maladies cardiovasculaires</strong> : environ <strong>17 000</strong> décès par an.</li><li><strong>Maladies respiratoires chroniques</strong> : environ <strong>12 000</strong> décès par an.</li></ul>"},{"i":"3a119b43ca76","n":75,"o":"75-15","u":"Epidémiologie","t":"Connaître l’impact sur la mortalité cardiovasculaire","q":"Quel est l'impact général du tabac sur le risque de développer une maladie cardiovasculaire ?","a":"<p>Le tabac multiplie par environ <strong>20</strong> le risque de développer une maladie cardiovasculaire.</p>"},{"i":"844861eb8ad2","n":75,"o":"75-15","u":"Epidémiologie","t":"Connaître l’impact sur la mortalité cardiovasculaire","q":"Le tabac est-il un facteur de risque pour d'autres pathologies cardiovasculaires que l'IDM et l'AOMI ?","a":"<p>Oui, le tabac est également un facteur de risque pour :</p><ul><li>L'<strong>AVC</strong> (accident vasculaire cérébral), avec un RR ≈ 1,5-2.</li><li>L'<strong>anévrisme de l'aorte abdominale</strong>.</li><li>L'<strong>HTA</strong> (hypertension artérielle) et la <strong>cardiopathie hypertensive</strong>.</li></ul>"},{"i":"9ab96c93f2b9","n":75,"o":"75-15","u":"Epidémiologie","t":"Connaître l’impact sur la mortalité cardiovasculaire","q":"Quel est l'impact du tabac sur le risque d'infarctus du myocarde et d'artériopathie oblitérante des membres inférieurs (AOMI) ?","a":"<p>Le tabac augmente le risque :</p><ul><li>D'<strong>infarctus du myocarde (IDM)</strong> avec un RR ≈ 3. Il est le <strong>2<sup>e</sup> facteur de risque d'IDM</strong> après la dyslipidémie, avec un <strong>effet-dose et sans dose-seuil</strong>.</li><li>D'<strong>artériopathie oblitérante des membres inférieurs (AOMI)</strong> avec un RR ≈ 2-7, et <strong>90 % des patients atteints d'AOMI sont fumeurs</strong>.</li></ul>"},{"i":"cebd7b303a23","n":75,"o":"75-15","u":"Epidémiologie","t":"Connaître l’impact sur la mortalité cardiovasculaire","q":"Le tabac est-il un facteur de risque cardiovasculaire évitable et touche-t-il spécifiquement certaines populations ?","a":"<p>Oui, le tabac est la <strong>1<sup>re</sup> cause de maladie cardiovasculaire évitable</strong>. Il est notamment le <strong>1<sup>er</sup> facteur de risque cardiovasculaire de la femme non ménopausée</strong>. L'effet est plus marqué chez les <strong>femmes</strong>, les <strong>hommes jeunes</strong> et les <strong>grands fumeurs</strong>.</p>"},{"i":"d5821dc1884b","n":75,"o":"75-15","u":"Epidémiologie","t":"Connaître l’impact sur la mortalité cardiovasculaire","q":"Quel est le risque de complications cardiovasculaires associé à l'association tabac et contraception œstroprogestative ?","a":"<p>L'association tabac et contraception œstroprogestative <strong>majore le risque thromboembolique</strong>.</p>"},{"i":"56a7a3b7e530","n":75,"o":"75-16","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme et celles des principales maladies liées au tabac","q":"Quel est le poids attribuable du tabac pour les cancers et les maladies cardiovasculaires en France ?","a":"<ul><li><strong>Cancers</strong> : Le tabac est responsable d'environ <strong>25 %</strong> des cancers et est le <strong>premier facteur de risque évitable</strong> de cancer.</li><li><strong>Maladies cardiovasculaires</strong> : Le tabac est la cause d'environ <strong>10 %</strong> des affections cardiovasculaires et multiplie le risque cardiovasculaire par <strong>20</strong>.</li></ul>"},{"i":"74a56687d009","n":75,"o":"75-16","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme et celles des principales maladies liées au tabac","q":"Quelles sont les trois grandes familles de maladies attribuables au tabagisme en France ?","a":"<ul><li>Les <strong>cancers</strong></li><li>Les <strong>maladies cardiovasculaires</strong></li><li>Les <strong>maladies respiratoires</strong></li></ul>"},{"i":"c684eabbd68c","n":75,"o":"75-16","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme et celles des principales maladies liées au tabac","q":"Comment peut-on décrire la prévalence du tabagisme en France chez les adultes de 18 à 75 ans ?","a":"<p>Le tabagisme touche environ <strong>15 millions</strong> de personnes en France, représentant environ <strong>33 %</strong> des 18-75 ans. Parmi eux, environ <strong>12 millions</strong> sont des fumeurs quotidiens.</p>"},{"i":"c93e06b05da9","n":75,"o":"75-16","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme et celles des principales maladies liées au tabac","q":"Quelles sont les principales maladies respiratoires liées au tabagisme ?","a":"<ul><li>La <strong>BPCO</strong> (bronchopneumopathie chronique obstructive)</li><li>L'<strong>emphysème</strong></li><li>La <strong>bronchite chronique</strong></li><li>L'<strong>aggravation de l'asthme</strong></li></ul>"},{"i":"36a306d61cc6","n":75,"o":"75-17","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme passif, les grandes notions de sur-risque","q":"Quel est le sur-risque de décès cardiovasculaire chez un adulte exposé au tabagisme passif ?","a":"<p>Le risque de <strong>décès cardiovasculaire</strong> est augmenté d'environ <strong>20 à 30 %</strong> chez l'adulte exposé au tabagisme passif.</p>"},{"i":"3d31b66fdc86","n":75,"o":"75-17","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme passif, les grandes notions de sur-risque","q":"Quel est le sur-risque de cancer pulmonaire chez un adulte exposé au tabagisme passif ?","a":"<p>Le risque de <strong>cancer pulmonaire</strong> est augmenté d'environ <strong>25 %</strong> chez l'adulte exposé au tabagisme passif.</p>"},{"i":"d758b114b332","n":75,"o":"75-17","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme passif, les grandes notions de sur-risque","q":"Quelle est la particularité du tabagisme passif en termes de seuil de risque ?","a":"<p>Il n'existe <strong>pas de seuil sans risque</strong> pour le tabagisme passif : même à faibles doses, il augmente le risque de maladie.</p>"},{"i":"fcf8eea01cde","n":75,"o":"75-17","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme passif, les grandes notions de sur-risque","q":"Quels sont les principaux risques pour la santé de l'enfant ou du nourrisson exposés au tabagisme passif ?","a":"<ul><li>Infections <strong>ORL</strong> (notamment les otites)</li><li>Infections <strong>pulmonaires</strong> (comme la bronchite)</li><li><strong>Asthme</strong></li><li><strong>Mort subite du nourrisson</strong></li></ul>"},{"i":"3d207d6ab8aa","n":75,"o":"75-19","u":"Diagnostic positif","t":"Savoir dépister la consommation de tabac","q":"Comment doit-on évaluer la quantité de tabac consommée et quelles sont les équivalences de certains produits par rapport aux cigarettes manufacturées ?","a":"<p>La quantité de tabac est évaluée en <strong>paquets-années</strong>, calculée par la formule : (nombre de paquets/jour) × (nombre d'années de tabagisme).</p><p>Les équivalences sont :</p><ul><li>1 cigarette roulée = <strong>2 cigarettes</strong> manufacturées</li><li>1 cigarillo = <strong>4 cigarettes</strong> manufacturées</li><li>1 joint de cannabis = <strong>4 cigarettes</strong> manufacturées</li><li>1 chicha = <strong>40 cigarettes</strong> manufacturées</li></ul>"},{"i":"58f3df51e462","n":75,"o":"75-19","u":"Diagnostic positif","t":"Savoir dépister la consommation de tabac","q":"Comment dépiste-t-on systématiquement la consommation de tabac chez un patient ?","a":"<p>Le dépistage systématique de la consommation de tabac chez tout patient repose sur une <strong>question simple</strong> : « Fumez-vous ? »</p>"},{"i":"6331b128bef4","n":75,"o":"75-19","u":"Diagnostic positif","t":"Savoir dépister la consommation de tabac","q":"Quel est le piège classique concernant le paquet-année dans l'évaluation du risque lié au tabagisme ?","a":"<p>Le piège classique est de considérer le paquet-année comme un bon évaluateur du risque. En réalité, si la <strong>quantité</strong> de tabac augmente le risque de cancer avec un facteur puissance 2, la <strong>durée d'exposition</strong> au tabac a un impact bien plus important, avec un facteur puissance 4.</p>"},{"i":"9630f5d7d166","n":75,"o":"75-19","u":"Diagnostic positif","t":"Savoir dépister la consommation de tabac","q":"Quels sont les paramètres à évaluer pour décrire la consommation de tabac d'un patient ?","a":"<p>Pour caractériser la consommation de tabac d'un patient, il faut évaluer :</p><ul><li>Le <strong>mode</strong> de consommation (avec ses équivalences)</li><li>L'<strong>âge de début</strong></li><li>La <strong>durée</strong> du tabagisme</li><li>La <strong>quantité</strong> consommée</li></ul>"},{"i":"373fd0927a86","n":75,"o":"75-2","u":"Définition","t":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d’évaluer cette dépendance","q":"Comment évalue-t-on les dépendances psychologique et comportementale au tabac ?","a":"<p>Les dépendances psychologique et comportementale au tabac s'apprécient sur la présence de <strong>craving</strong>, qui représente un facteur de risque de rechute.</p><ul><li>La <strong>dépendance psychologique</strong> est liée aux « effets positifs » associés à la cigarette (se relaxer, réfléchir, effet coupe-faim).</li><li>La <strong>dépendance comportementale (sociale)</strong> est liée aux situations répétées associées à la cigarette (moments de convivialité, association au café, à l'alcool, au cannabis) déclenchant une envie « réflexe ».</li></ul>"},{"i":"37f7fa9f7dff","n":75,"o":"75-2","u":"Définition","t":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d’évaluer cette dépendance","q":"Comment la dépendance au tabac est-elle définie selon la CIM-10 ?","a":"<p>Selon la CIM-10, la dépendance au tabac est définie par la présence d'au moins <strong>3 manifestations au cours de la dernière année</strong>. Ces manifestations incluent :</p><ul><li>Un désir compulsif de consommer.</li><li>Des difficultés à contrôler l'usage (début, quantité, arrêt).</li><li>Un syndrome de sevrage à l'arrêt.</li><li>Une tolérance (augmentation des doses).</li><li>Un désintérêt pour les autres plaisirs.</li><li>Une poursuite de la consommation malgré les conséquences néfastes.</li></ul>"},{"i":"62695f1ddaa6","n":75,"o":"75-2","u":"Définition","t":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d’évaluer cette dépendance","q":"Quels sont les principaux types de dépendance entraînés par le tabac ?","a":"<p>Le tabac entraîne plusieurs types de dépendance, qu'il faut évaluer :</p><ul><li>La <strong>dépendance physique (pharmacologique)</strong>.</li><li>La <strong>dépendance psychologique</strong>.</li><li>La <strong>dépendance comportementale (sociale)</strong>.</li></ul>"},{"i":"eebff1e1b8fa","n":75,"o":"75-2","u":"Définition","t":"Connaître les principaux types de dépendance entraînés par le tabac et la façon d’évaluer cette dépendance","q":"Comment évalue-t-on la dépendance physique au tabac et quel est son mécanisme ?","a":"<p>La dépendance physique au tabac, liée directement à la nicotine, s'évalue principalement par le <strong>test de Fagerström</strong>. Son mécanisme implique :</p><ul><li>Un pic de concentration rapide de nicotine au cerveau (<strong>« effet shoot »</strong>).</li><li>La fixation de la nicotine sur les <strong>récepteurs cholinergiques nicotiniques</strong>.</li><li>La stimulation du <strong>système de récompense</strong> par libération de dopamine.</lI></ul>"},{"i":"a29a15767ced","n":75,"o":"75-20","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic de la dépendance","q":"Comment la dépendance au tabac est-elle médicalement diagnosticable en tenant compte des trois registres principaux ?","a":"<p>Le diagnostic de dépendance au tabac repose sur l'évaluation de trois registres :</p><ul><li>La <strong>dépendance pharmacologique</strong>.</li><li>La <strong>dépendance psychologique</strong>.</li><li>La <strong>dépendance comportementale</strong>.</li></ul>"},{"i":"a8bb4e36ba7a","n":75,"o":"75-20","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic de la dépendance","q":"Comment la dépendance psychologique et comportementale au tabac est-elle évaluée ?","a":"<p>La dépendance psychologique et comportementale est évaluée par la <strong>présence de craving</strong> (ou envie irrépressible de fumer), qui est un facteur de risque important de rechute.</p>"},{"i":"ad9029e0e415","n":75,"o":"75-20","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic de la dépendance","q":"Comment évalue-t-on le niveau de dépendance au tabac à l'aide de la version simplifiée du Test de Fagerström ?","a":"<p>La version simplifiée du Test de Fagerström attribue un score en fonction de deux questions :</p><ul><li><strong>Nombre de cigarettes par jour :</strong></li><ul><li>≤ 10 → 0 point</li><li>11-20 → 1 point</li><li>21-30 → 2 points</li><li>≥ 31 → 3 points</li></ul><li><strong>Délai entre le réveil et la 1ère cigarette :</strong></li><ul><li>≤ 5 min → 3 points</li><li>6-30 min → 2 points</li><li>31-60 min → 1 point</li><li>> 60 min → 0 point</li></ul></ul><p>L'<strong>interprétation</strong> du score total (version simplifiée) est la suivante :</p><ul><li><strong>0-1</strong> : non dépendant</li><li><strong>2-3</strong> : dépendance modérée</li><li><strong>4-6</strong> : dépendance forte</li></ul>"},{"i":"f852fc2fbad7","n":75,"o":"75-20","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic de la dépendance","q":"Quel outil est spécifiquement utilisé pour évaluer la dépendance pharmacologique au tabac et quelles sont ses caractéristiques principales ?","a":"<p>L'outil spécifique pour évaluer la dépendance pharmacologique est le <strong>Test de Fagerström</strong>.</p><ul><li>Il existe en <strong>version complète (6 questions)</strong> avec un score allant de 0 à 10.</li><li>Il existe une <strong>version simplifiée (2 questions)</strong>, considérées comme les plus discriminantes, sur le nombre de cigarettes par jour et le délai avant la première cigarette après le réveil.</li><li>Les <strong>4 premières questions de la version complète</strong> sont souvent jugées les plus utiles.</li></ul>"},{"i":"0aafcc0f1602","n":75,"o":"75-21","u":"Diagnostic positif","t":"Connaître les signes de sevrage en tabac","q":"Quels sont les signes cliniques du syndrome de sevrage tabagique concernant l'humeur et le sommeil ?","a":"<ul><li><strong>Humeur</strong> : Humeur dépressive, irritabilité, frustration, colère.</li><li><strong>Sommeil</strong> : Insomnie.</li></ul>"},{"i":"6b0320bf445a","n":75,"o":"75-21","u":"Diagnostic positif","t":"Connaître les signes de sevrage en tabac","q":"Quelle est l'origine du syndrome de sevrage tabagique et quel est son impact principal sur l'arrêt du tabac ?","a":"<p>Le syndrome de sevrage tabagique est consécutif au <strong>manque de nicotine</strong>. Il constitue le <strong>facteur de rechute principal</strong> après un arrêt brutal ou une diminution significative de la consommation de tabac.</p>"},{"i":"de4af2b64480","n":75,"o":"75-21","u":"Diagnostic positif","t":"Connaître les signes de sevrage en tabac","q":"Quels sont les signes cliniques du syndrome de sevrage tabagique concernant les fonctions cognitives et l'appétit ?","a":"<ul><li><strong>Cognitif</strong> : Anxiété, difficultés de concentration.</li><li><strong>Appétit / poids</strong> : Augmentation de l'appétit, prise de poids.</li></ul>"},{"i":"305edada04cf","n":75,"o":"75-22","u":"Diagnostic positif","t":"Connaître les complications médicales non psychiatriques","q":"Quelles sont les principales localisations de cancers causés par l'addiction au tabac ?","a":"<p>L'addiction au tabac est responsable de nombreux cancers, notamment :</p><ul><li><strong>Cancers du poumon</strong> (90% des cas)</li><li>Cancers <strong>ORL / VADS</strong> (cavités nasales, bouche, pharynx, larynx)</li><li>Cancers <strong>digestifs</strong> (œsophage épidermoïde, estomac, foie, pancréas, côlon-rectum)</li><li>Cancers <strong>urologiques</strong> (rein, vessie)</li><li>Cancers <strong>gynécologiques</strong> (sein, ovaire, col de l'utérus)</li><li><strong>Leucémies myéloïdes</strong> (via le benzène)</li></ul>"},{"i":"3d9b765138bf","n":75,"o":"75-22","u":"Diagnostic positif","t":"Connaître les complications médicales non psychiatriques","q":"Quelles sont les complications liées à l'addiction au tabac survenant pendant la grossesse et les atteintes dermatologiques associées ?","a":"<p>Pendant la grossesse, l'addiction au tabac peut entraîner :</p><ul><li><strong>Fausse couche</strong></li><li><strong>Mort fœtale in utero</strong></li><li><strong>Rupture prématurée des membranes</strong></li><li><strong>Accouchement prématuré</strong></li><li><strong>RCIU</strong> (Retard de Croissance Intra-Utérin)</li><li><strong>GEU</strong> (Grossesse Extra-Utérine)</li><li><strong>Placenta praevia</strong></li><li><strong>Hématome rétroplacentaire</strong></li></ul><p>Les atteintes dermatologiques incluent :</p><ul><li><strong>Vieillissement cutané accéléré</strong></li><li><strong>Coloration des ongles</strong></li><li><strong>Sécheresse cutanée</strong></li><li><strong>Aggravation de l'acné</strong></li><li><strong>Maladie de Buerger</strong></li></ul>"},{"i":"9dc5f347be31","n":75,"o":"75-22","u":"Diagnostic positif","t":"Connaître les complications médicales non psychiatriques","q":"Quelles sont les complications cardiovasculaires et respiratoires liées à l'addiction au tabac ?","a":"<p>Les complications cardiovasculaires et respiratoires liées à l'addiction au tabac comprennent :</p><ul><li><strong>Cardiovasculaires</strong> : <strong>IDM</strong> (Infarctus du Myocarde), <strong>AOMI</strong> (Artériopathie Oblitérante des Membres Inférieurs), <strong>AVC</strong> (Accident Vasculaire Cérébral), <strong>anévrisme de l'aorte abdominale</strong>, <strong>HTA</strong> (Hypertension Artérielle).</li><li><strong>Respiratoires</strong> : <strong>BPCO</strong> (Broncho-Pneumopathie Chronique Obstructive) évoluant vers l'insuffisance respiratoire sans sevrage, <strong>emphysème</strong>, <strong>bronchite chronique</strong>, <strong>asthme</strong> (exacerbations, mauvais contrôle).</li></ul>"},{"i":"4a2cb5cd0fd3","n":75,"o":"75-24","u":"Prise en charge","t":"Moment du sevrage : connaître la proposition d'aide à l'arrêt à chaque contact avec un professionnel de santé","q":"Quelle est l'approche recommandée pour la prise en charge de l'addiction au tabac lors de chaque contact avec un professionnel de santé, conformément aux recommandations de santé publique ?","a":"<p>L'approche recommandée est le <strong>conseil minimal</strong>, structuré selon la méthode des <strong>5 A</strong> :</p><ul><li><strong>Ask</strong> : Demander à la personne si elle fume.</li><li><strong>Assess</strong> : Évaluer son tabagisme (degré de dépendance, motivation).</li><li><strong>Advise</strong> : Conseiller à chaque fumeur d'arrêter de fumer de manière claire et personnalisée.</li><li><strong>Assist</strong> : Évoquer la palette des aides et accompagnements disponibles pour l'arrêt du tabac.</li><li><strong>Arrange</strong> : Proposer un support écrit d'information pour appuyer ce conseil.</li></ul>"},{"i":"603ddb689910","n":75,"o":"75-24","u":"Prise en charge","t":"Moment du sevrage : connaître la proposition d'aide à l'arrêt à chaque contact avec un professionnel de santé","q":"Dans quelles situations spécifiques faut-il envisager un sevrage tabagique rapide chez un patient fumeur ?","a":"<p>Trois situations cliniques imposent d'envisager un sevrage tabagique rapide :</p><ul><li>La <strong>grossesse</strong>.</li><li>La <strong>découverte d'une maladie liée au tabac</strong>.</li><li>Une <strong>chirurgie programmée</strong> (un arrêt <strong>6 à 8 semaines</strong> avant l'intervention diminue significativement la morbi-mortalité opératoire).</li></ul>"},{"i":"21515c247d1d","n":75,"o":"75-25","u":"Prise en charge","t":"Connaître les moyens de prévention primaire et secondaire","q":"Quelles sont les mesures de prévention primaire de l'addiction au tabac dont l'efficacité a été universellement vérifiée ?","a":"<p>Les mesures dont l'efficacité a été universellement vérifiée incluent :</p><ul><li>Une <strong>augmentation forte et régulièrement répétée des prix</strong> du tabac.</li><li>L'<strong>interdiction de la publicité</strong>, qu'elle soit directe ou indirecte.</li><li>L'<strong>interdiction de fumer dans les lieux publics clos et les lieux de travail</strong>.</li><li>L'<strong>interdiction de la vente de tabac aux moins de 18 ans</strong>.</li><li>L'apposition d'<strong>avertissements sanitaires illustrés sur les paquets</strong> de tabac.</li></ul>"},{"i":"459535703b02","n":75,"o":"75-25","u":"Prise en charge","t":"Connaître les moyens de prévention primaire et secondaire","q":"Citez les principales lois françaises qui ont encadré la prévention du tabagisme.","a":"<p>Les principales lois françaises encadrant le cadre légal de la prévention du tabagisme sont :</p><ul><li>La <strong>Loi Veil (1976)</strong>.</li><li>La <strong>Loi Évin (1991)</strong>.</li><li>Le <strong>Décret Bertrand (2006)</strong>.</li></ul>"},{"i":"f9403b20faaf","n":75,"o":"75-25","u":"Prise en charge","t":"Connaître les moyens de prévention primaire et secondaire","q":"Quels sont les axes d'intervention du Programme National de Réduction du Tabagisme (PNRT) 2018-2022 ?","a":"<p>Les axes d'intervention du PNRT 2018-2022 sont :</p><ul><li>Protéger les <strong>enfants de l'entrée dans le tabagisme</strong>.</li><li>Accompagner les <strong>fumeurs vers le sevrage</strong>.</li><li>Agir sur l'<strong>économie du tabac</strong>.</li></ul><p>L'objectif affiché est d'atteindre la <strong>première génération sans tabac d'ici 2032 (< 5 % de fumeurs)</strong>.</p>"},{"i":"6dc75d7849ff","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quels sont les traitements pharmacologiques de première intention pour la dépendance au tabac ?","a":"<p>Le traitement pharmacologique de première intention pour la dépendance au tabac repose sur les <strong>substituts nicotiniques</strong>. La <strong>cigarette électronique</strong> peut également être utilisée.</p>"},{"i":"98d78d218e12","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quels sont les effets indésirables classiques des substituts nicotiniques ?","a":"<p>Les effets indésirables sont généralement modérés et régressifs : <strong>céphalées</strong>, <strong>palpitations</strong>, <strong>érythème</strong> ou <strong>prurit</strong> au point d'application pour les formes transdermiques, et <strong>troubles buccaux</strong> pour les formes orales.</p>"},{"i":"a02c67c3dce7","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quels sont les traitements pharmacologiques de seconde et dernière intention pour la dépendance au tabac, en dehors des substituts nicotiniques ?","a":"<p>En dehors des substituts nicotiniques, la <strong>varénicline</strong> est utilisée en seconde intention et le <strong>bupropion</strong> en dernière intention.</p>"},{"i":"ac8da1a60eec","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quel est le principe de dosage des substituts nicotiniques ?","a":"<p>Le dosage est initialement estimé à environ <strong>1 mg de nicotine par cigarette fumée</strong> (par exemple, environ 20 mg/jour pour un paquet/jour), puis il est <strong>adapté aux signes de sur- ou sous-dosage</strong>. La diminution est progressive sur une période d'au moins <strong>3 mois</strong>.</p>"},{"i":"e42704e9a84a","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quelle est l'efficacité et les contre-indications des substituts nicotiniques ?","a":"<p>Les substituts nicotiniques multiplient par <strong>2 à 3</strong> le taux d'arrêt du tabac à 6 mois. Il n'y a <strong>aucune contre-indication absolue</strong>, mais une prudence est requise pendant la <strong>grossesse</strong> et en cas de <strong>pathologie cardiovasculaire</strong>.</p>"},{"i":"eae5664ab455","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quels sont les différents types de prise en charge pour la dépendance au tabac ?","a":"<p>La prise en charge de la dépendance au tabac associe des moyens non pharmacologiques et pharmacologiques.</p>"},{"i":"f32f5e89ee32","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quelles sont les méthodes non pharmacologiques de prise en charge de la dépendance au tabac ?","a":"<ul><li>Le <strong>conseil minimal</strong>, pratiqué par tout professionnel de santé.</li><li>Les <strong>psychothérapies</strong> : entretien motivationnel, psychothérapie de soutien, et thérapies cognitivo-comportementales (TCC).</li><li>Les <strong>aides</strong> : accompagnement téléphonique (ex : Tabac Info Service) ou consultation de tabacologie.</li></ul>"},{"i":"f9ffa7cbf1ea","n":75,"o":"75-26","u":"Prise en charge","t":"Connaître les traitements de la dépendance au tabac (pharmacologiques et non pharmacologiques)","q":"Quelles sont les différentes formes de substituts nicotiniques et leurs modalités d'association ?","a":"<ul><li>Les formes <strong>transdermiques</strong> (timbres/patchs) : elles peuvent être de 16h ou 24h.</li><li>Les formes <strong>orales</strong> : gommes, comprimés, pastilles, inhaleurs, sprays.</li></ul><p>Ces différentes formes peuvent être associées entre elles.</p>"},{"i":"1eba8cbc55ce","n":75,"o":"75-27","u":"Prise en charge","t":"Connaître les outils institutionnels (tabac info service)","q":"Qu'est-ce que Tabac Info Service ?","a":"<p>Tabac Info Service est une <strong>ligne d'accompagnement téléphonique</strong> destinée à aider à l'arrêt du tabac.</p>"},{"i":"3f1633e59815","n":75,"o":"75-27","u":"Prise en charge","t":"Connaître les outils institutionnels (tabac info service)","q":"Quel est le montant du forfait d'aide au sevrage tabagique et qui en bénéficie ?","a":"<p>Le forfait d'aide au sevrage est de <strong>150 € par an</strong> et il est accessible à <strong>tous les assurés</strong>.</p>"},{"i":"a256cea391bd","n":75,"o":"75-27","u":"Prise en charge","t":"Connaître les outils institutionnels (tabac info service)","q":"À qui s'adresse la consultation de tabacologie ?","a":"<p>La consultation de tabacologie est destinée aux personnes rencontrant des <strong>difficultés à arrêter de consommer du tabac</strong>.</p>"},{"i":"1ec427a0c8ba","n":75,"o":"75-6","u":"Epidémiologie","t":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","q":"Quel est l'âge moyen du début de la consommation tabagique quotidienne en France, selon les données épidémiologiques ?","a":"<p>L'âge moyen du début d'une consommation quotidienne de tabac en France est d'environ <strong>15 ans</strong>.</p>"},{"i":"5f854fc46c37","n":75,"o":"75-6","u":"Epidémiologie","t":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","q":"Quel pourcentage des fumeurs réguliers présente des signes de dépendance au tabac ?","a":"<p>Environ <strong>50 %</strong> des fumeurs réguliers présentent des signes de dépendance au tabac.</p>"},{"i":"78909e8c2633","n":75,"o":"75-6","u":"Epidémiologie","t":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","q":"Quelle est la mortalité mondiale liée au tabac et quel pourcentage des fumeurs mourront prématurément de cette cause ?","a":"<p>Au niveau mondial, le tabac est responsable d'environ <strong>1 décès sur 10</strong>. Environ <strong>50 %</strong> des fumeurs mourront prématurément d'une maladie due au tabac.</p>"},{"i":"a2a7d8bc498d","n":75,"o":"75-6","u":"Epidémiologie","t":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","q":"Quelle est la mortalité annuelle en France liée au tabac et est-ce une cause évitable ?","a":"<p>En France, le tabac est responsable d'environ <strong>75 000 décès prématurés par an</strong>. Il s'agit de la <strong>première cause de décès évitable</strong>.</p>"},{"i":"effa3734f443","n":75,"o":"75-6","u":"Epidémiologie","t":"Connaître l’âge de début, le pourcentage de dépendants et la mortalité mondiale et française liée au tabac et les risques","q":"Quel est le facteur de risque le plus important de complications liées à l'intoxication tabagique et comment agit-il sur le risque de cancer ?","a":"<p>Le facteur de risque le plus important de complications est la <strong>durée d'intoxication</strong>. Doubler la dose de tabac multiplie le risque de cancer par <strong>2</strong>, mais doubler la durée d'exposition le multiplie par <strong>16 à 23</strong>.</p>"},{"i":"7bd45e0f478f","n":75,"o":"75-8","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les hommes et les femmes","q":"Quelles sont les tendances d'évolution du tabagisme observées chez les hommes et les femmes en France, notamment pour les différentes tranches d'âge ?","a":"<p>Les tendances observées sont :</p><ul><li>La diminution du tabagisme est <strong>plus rapide et plus marquée chez les hommes</strong>, et ce à tous les âges.</li><li>Chez les femmes, une <strong>diminution</strong> est observée pour les tranches d'âge <strong>inférieures à 55 ans</strong>.</li><li>Cependant, une <strong>augmentation</strong> du tabagisme est constatée chez les femmes de <strong>55 à 75 ans</strong>, expliquée par l'arrivée dans ces tranches d'âge de générations ayant commencé à fumer dès les années 1960.</li></ul>"},{"i":"a033264aadb1","n":75,"o":"75-8","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les hommes et les femmes","q":"Quelle est la prévalence globale de la consommation de tabac (toutes formes confondues) dans la population française âgée de 18 à 75 ans ?","a":"<p>La prévalence de la consommation de tabac (toutes formes confondues) chez les 18-75 ans en France est de <strong>33 %</strong>.</p>"},{"i":"e9dded0911d7","n":75,"o":"75-8","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les hommes et les femmes","q":"Comment la prévalence du tabagisme se distingue-t-elle entre les hommes et les femmes en France (18-75 ans), aussi bien pour la consommation globale que quotidienne ?","a":"<p>En France (18-75 ans) :</p><ul><li>Le tabagisme (toutes formes) concerne <strong>35 % des hommes</strong> et <strong>25 % des femmes</strong>.</li><li>Le tabagisme quotidien concerne <strong>27,5 % des hommes</strong> et <strong>20,7 % des femmes</strong>.</li></ul>"},{"i":"12da158d3c92","n":75,"o":"75-9","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les jeunes","q":"Quelle est la tendance de l'expérimentation de la chicha chez les élèves de 3ᵉ entre 2018 et 2021 ?","a":"<p>L'expérimentation de la chicha chez les élèves de 3ᵉ est en <strong>recul</strong>, passant de <strong>26,2 % en 2018</strong> à <strong>20 % en 2021</strong>.</p>"},{"i":"695b922187e9","n":75,"o":"75-9","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les jeunes","q":"Quelle est la tendance observée pour l'usage quotidien du tabac chez les élèves de 3ᵉ entre 2010 et 2021 ?","a":"<p>L'usage quotidien du tabac chez les élèves de 3ᵉ est passé de <strong>15,6 % en 2010</strong> à <strong>3,7 % en 2021</strong>.</p>"},{"i":"7376f24f5683","n":75,"o":"75-9","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les jeunes","q":"Quelle est la tendance observée pour l'expérimentation du tabac chez les élèves de 3ᵉ entre 2010 et 2021 ?","a":"<p>L'expérimentation du tabac chez les élèves de 3ᵉ est passée de <strong>51,8 % en 2010</strong> à <strong>29,1 % en 2021</strong>.</p>"},{"i":"b7f3fae88a63","n":75,"o":"75-9","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les jeunes","q":"Quelle est l'évolution récente de la consommation de tabac chez les jeunes en France ?","a":"<p>La consommation de tabac chez les jeunes est en <strong>baisse importante</strong>.</p>"},{"i":"d0ce10edd190","n":75,"o":"75-9","u":"Epidémiologie","t":"Connaître l’épidémiologie du tabagisme chez les jeunes","q":"Quelle est la part des élèves de 3ᵉ ayant déjà expérimenté la cigarette électronique en 2021 ?","a":"<p>En 2021, <strong>34,2 %</strong> des élèves de 3ᵉ ont expérimenté la <strong>cigarette électronique</strong>.</p>"}]};